INSERT INTO series (id, name, userId) VALUES ('sr_saison1', 'Saison 1', 'ibaVT5FhANHbVkMp1Jj4bhQpkd1U7d8s');
INSERT INTO topics (id, name) VALUES ('tp_liberte', 'Liberté');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_928329b3', 'L''esclave qui n''est pas capable d''assumer sa révolte ne mérite pas que l''on s''apitoie sur son sort. Seule la lutte libère.', 'Thomas Sankara', 'Burkinabé', 'Wikiquote FR — ''L''émancipation des femmes et la lutte de libération de l''Afrique'', Pathfinder Press, 2001, p. 46','["2025-01-01","2026-02-04","2027-03-10","2028-04-12","2029-05-16","2030-06-19"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_54029fbb', 'Lorsque le peuple se met debout, l''impérialisme tremble.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — cité dans ''Figures de la révolution africaine'', Saïd Bouamama, La Découverte, 2017, p. 277','["2025-01-02","2026-02-05","2027-03-11","2028-04-13","2029-05-17","2030-06-20"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_311659df', 'For to be free is not merely to cast off one''s chains, but to live in a way that respects and enhances the freedom of others.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995 — Nelson Mandela Foundation','["2025-01-03","2026-02-06","2027-03-12","2028-04-14","2029-05-18","2030-06-21"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f47ea32a', 'On naît libre et partout l''homme est dans les fers.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre I, Chapitre 1, 1762','["2025-01-04","2026-02-07","2027-03-13","2028-04-15","2029-05-19","2030-06-22"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e9e9ff52', 'L''homme est condamné à être libre.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945','["2025-01-05","2026-02-08","2027-03-14","2028-04-16","2029-05-20","2030-06-23"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5bba9e35', 'Freedom is never voluntarily given by the oppressor; it must be demanded by the oppressed.', 'Martin Luther King', 'Américain', '''Letter from Birmingham Jail'', 16 avril 1963 — The King Center, Atlanta','["2025-01-06","2026-02-09","2027-03-15","2028-04-17","2029-05-21","2030-06-24"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d7e6c666', 'Those who would give up essential Liberty, to purchase a little temporary Safety, deserve neither Liberty nor Safety.', 'Benjamin Franklin', 'Américain', 'Lettre à l''Assemblée de Pennsylvanie, novembre 1755','["2025-01-07","2026-02-10","2027-03-16","2028-04-18","2029-05-22","2030-06-25"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_821df3ac', 'Τῶν ὄντων τὰ μέν ἐστιν ἐφ᾽ ἡμῖν, τὰ δὲ οὐκ ἐφ᾽ ἡμῖν.', 'Épictète', 'Grec/Phrygien', '''Ἐγχειρίδιον (Enkheiridion)'' (Enchiridion), §1, ~135 ap. J.-C.','["2025-01-08","2026-02-11","2027-03-17","2028-04-19","2029-05-23","2030-06-26"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_43df32af', 'Non est ad astra mollis e terris via. / Non quia difficilia sunt non audemus, sed quia non audemus difficilia sunt.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre CIV','["2025-01-09","2026-02-12","2027-03-18","2028-04-20","2029-05-24","2030-06-27"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4a17e5f9', 'La servitude volontaire est la plus vile de toutes les servitudes.', 'Étienne de La Boétie', 'Français', '''Discours de la servitude volontaire'', ~1548','["2025-01-10","2026-02-13","2027-03-19","2028-04-21","2029-05-25","2030-06-28"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0b21c825', 'La liberté de la femme est la condition sine qua non de la liberté de tout le peuple.', 'Thomas Sankara', 'Burkinabé', 'Discours du 8 mars 1987 — thomassankara.net | Wikiquote FR','["2025-01-11","2026-02-14","2027-03-20","2028-04-22","2029-05-26","2030-06-29"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_828f2835', 'Emancipate yourselves from mental slavery, none but ourselves can free our minds.', 'Bob Marley', 'Jamaïcain', '''Redemption Song'', album ''Uprising'', Island Records, 1980','["2025-01-12","2026-02-15","2027-03-21","2028-04-23","2029-05-27","2030-06-30"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4e33bbcd', 'I am not free while any woman is unfree, even when her chains are very different from my own.', 'Audre Lorde', 'Américaine', '''The Master''s Tools Will Never Dismantle the Master''s House'', 1984 — ''Sister Outsider'', Crossing Press','["2025-01-13","2026-02-16","2027-03-22","2028-04-24","2029-05-28","2030-07-01"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_af8858ed', 'The struggle is my life. I will continue fighting for freedom until the end of my days.', 'Nelson Mandela', 'Sud-Africain', 'Déclaration de Johannesburg, 26 juin 1961 — Nelson Mandela Foundation','["2025-01-14","2026-02-17","2027-03-23","2028-04-25","2029-05-29","2030-07-02"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4c139e11', 'If there is no struggle, there is no progress.', 'Frederick Douglass', 'Américain', 'Discours ''West India Emancipation'', 4 août 1857','["2025-01-15","2026-02-18","2027-03-24","2028-04-26","2029-05-30","2030-07-03"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_25a29e79', 'Si les hommes naissaient libres, ils ne formeraient aucun concept du bien et du mal tant qu''ils demeureraient libres.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie IV, Proposition LXVIII, 1677','["2025-01-16","2026-02-19","2027-03-25","2028-04-27","2029-05-31","2030-07-04"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9d8c6228', 'Ni le Coran ni la Bible n''ont jamais pu réconcilier le riche et le pauvre.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio — Discours archivés','["2025-01-17","2026-02-20","2027-03-26","2028-04-28","2029-06-01","2030-07-05"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_919facd0', 'La liberté est absolument nécessaire pour le progrès des sciences et des arts libéraux.', 'Baruch Spinoza', 'Néerlandais', '''Tractatus Theologico-Politicus'', Chapitre XX, 1670','["2025-01-18","2026-02-21","2027-03-27","2028-04-29","2029-06-02","2030-07-06"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4142272d', 'Handle nur nach derjenigen Maxime, durch die du zugleich wollen kannst, daß sie ein allgemeines Gesetz werde.', 'Emmanuel Kant', 'Allemand', '''Grundlegung zur Metaphysik der Sitten'', Section II, 1785','["2025-01-19","2026-02-22","2027-03-28","2028-04-30","2029-06-03","2030-07-07"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_72f1e0ae', 'L''obéissance à la loi qu''on s''est prescrite à soi-même est liberté.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre I, Chapitre 8, 1762','["2025-01-20","2026-02-23","2027-03-29","2028-05-01","2029-06-04","2030-07-08"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e595d411', 'La béatitude n''est pas la récompense de la vertu, mais la vertu elle-même.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie V, Proposition XLII, 1677','["2025-01-21","2026-02-24","2027-03-30","2028-05-02","2029-06-05","2030-07-09"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a6dea7b0', 'La paix n''est pas l''absence de guerre; c''est une vertu, un état d''esprit, une disposition à la bienveillance, à la confiance, à la justice.', 'Baruch Spinoza', 'Néerlandais', '''Tractatus Politicus'', Chapitre V, §4, 1677','["2025-01-22","2026-02-25","2027-03-31","2028-05-03","2029-06-06","2030-07-10"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_57381926', 'Tout ce qui est excellent est aussi difficile que rare.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie V, Proposition XLII, Scolie, 1677','["2025-01-23","2026-02-26","2027-04-01","2028-05-04","2029-06-07","2030-07-11"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8de80b8b', 'Die Freiheit ist die Einsicht in die Notwendigkeit.', 'Georg Wilhelm Friedrich Hegel', 'Allemand', '''Enzyklopädie der philosophischen Wissenschaften'', §158, 1817','["2025-01-24","2026-02-27","2027-04-02","2028-05-05","2029-06-08","2030-07-12"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0078c154', 'Chacun peut penser ce qui lui plaît et dire ce qu''il pense.', 'Baruch Spinoza', 'Néerlandais', '''Tractatus Theologico-Politicus'', Chapitre XX, 1670','["2025-01-25","2026-02-28","2027-04-03","2028-05-06","2029-06-09","2030-07-13"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_08516da3', 'Nul ne peut désirer être heureux, bien agir et bien vivre sans désirer en même temps être, agir et vivre.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie IV, Proposition XXI, 1677','["2025-01-26","2026-03-01","2027-04-04","2028-05-07","2029-06-10","2030-07-14"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c6cc8a02', '道常無為而無不為。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 37, ~VIe siècle av. J.-C.','["2025-01-27","2026-03-02","2027-04-05","2028-05-08","2029-06-11","2030-07-15"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6f2f2fc1', 'Il n''est point de coexistence à venir qui ne soit fondée sur la rupture avec l''ordre colonialiste.', 'Aimé Césaire', 'Martiniquais', '''Discours sur le colonialisme'', Présence Africaine, 1955, p. 11','["2025-01-28","2026-03-03","2027-04-06","2028-05-09","2029-06-12","2030-07-16"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e26051a5', 'We prefer self-government with danger to servitude in tranquility.', 'Kwame Nkrumah', 'Ghanéen', 'Discours d''indépendance du Ghana, 6 mars 1957 — Archives du Ghana','["2025-01-29","2026-03-04","2027-04-07","2028-05-10","2029-06-13","2030-07-17"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_db99270d', 'ὁ τοῦ ἔρωτος δοῦλος μόνος ἐλεύθερός ἐστιν.', 'Platon', 'Grec', '''Φαῖδρος (Phaidros)'', 252a, ~370 av. J.-C.','["2025-01-30","2026-03-05","2027-04-08","2028-05-11","2029-06-14","2030-07-18"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_06df4890', 'La patrie ou la mort, nous vaincrons.', 'Thomas Sankara', 'Burkinabé', 'Cri de ralliement officiel de la révolution burkinabé, 1983-1987 — thomassankara.net','["2025-01-31","2026-03-06","2027-04-09","2028-05-12","2029-06-15","2030-07-19"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_721b207f', 'Je m''efforce non de rire des actions humaines, non de les déplorer, non de les détester, mais de les comprendre.', 'Baruch Spinoza', 'Néerlandais', '''Tractatus Politicus'', Chapitre I, §4, 1677 (posthume)','["2025-02-01","2026-03-07","2027-04-10","2028-05-13","2029-06-16","2030-07-20"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9df0ad54', 'L''activité la plus élevée que l''homme puisse atteindre est l''apprentissage pour la compréhension, car comprendre c''est être libre.', 'Baruch Spinoza', 'Néerlandais', '''Tractatus de Intellectus Emendatione'', §1, 1677','["2025-02-02","2026-03-08","2027-04-11","2028-05-14","2029-06-17","2030-07-21"]',  'verified', 'tp_liberte');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d981410b', 'Un peuple conscient ne saurait confier la défense de sa patrie à un groupe d''hommes, quelles que soient leurs compétences.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Wikiquote FR','["2025-02-03","2026-03-09","2027-04-12","2028-05-15","2029-06-18","2030-07-22"]',  'verified', 'tp_liberte');
INSERT INTO topics (id, name) VALUES ('tp_justice_et_egalite', 'Justice & Égalité');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_75e9159c', 'Injustice anywhere is a threat to justice everywhere.', 'Martin Luther King', 'Américain', '''Letter from Birmingham Jail'', 16 avril 1963 — The King Center, Atlanta','["2025-02-04","2026-03-10","2027-04-13","2028-05-16","2029-06-19","2030-07-23"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5ea76d4f', 'Il faut choisir entre le champagne pour quelques-uns et l''eau potable pour tous.', 'Thomas Sankara', 'Burkinabé', 'Le Monde, 23 décembre 2021 — thomassankara.net','["2025-02-05","2026-03-11","2027-04-14","2028-05-17","2029-06-20","2030-07-24"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a90a8a6a', 'No one is born hating another person because of the color of his skin, or his background, or his religion.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995, p. 622 — Nelson Mandela Foundation','["2025-02-06","2026-03-12","2027-04-15","2028-05-18","2029-06-21","2030-07-25"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dae0fb95', 'La justice sans force est impuissante, la force sans justice est tyrannique.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 298, 1670 (posthume)','["2025-02-07","2026-03-13","2027-04-16","2028-05-19","2029-06-22","2030-07-26"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_78d0d4f6', 'La négation de l''histoire et des réalisations intellectuelles des peuples africains noirs est le meurtre culturel.', 'Cheikh Anta Diop', 'Sénégalais', '''Civilisation ou Barbarie'', Présence Africaine, Paris, 1981, p. 10','["2025-02-08","2026-03-14","2027-04-17","2028-05-20","2029-06-23","2030-07-27"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5e5f3c58', 'La décolonisation n''est jamais un phénomène naturel, c''est une violence.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 5','["2025-02-09","2026-03-15","2027-04-18","2028-05-21","2029-06-24","2030-07-28"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b3700b83', 'Justice is the first virtue of social institutions.', 'John Rawls', 'Américain', '''A Theory of Justice'', Harvard University Press, 1971, p. 3','["2025-02-10","2026-03-16","2027-04-19","2028-05-22","2029-06-25","2030-07-29"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d6c28f98', 'La résistance à l''oppression est le plus sacré des droits.', 'Maximilien Robespierre', 'Français', 'Projet de Déclaration des droits de l''homme, Convention Nationale, 1793','["2025-02-11","2026-03-17","2027-04-20","2028-05-23","2029-06-26","2030-07-30"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1a267ed8', 'Lorsque les riches se font la guerre, ce sont les pauvres qui meurent.', 'Jean-Paul Sartre', 'Français', '''Le Diable et le Bon Dieu'', Gallimard, 1951','["2025-02-12","2026-03-18","2027-04-21","2028-05-24","2029-06-27","2030-07-31"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ae84b6e2', 'L''inégalité ne peut être supprimée que par l''établissement d''une nouvelle société où hommes et femmes jouiront de droits égaux.', 'Thomas Sankara', 'Burkinabé', 'Discours du 8 mars 1987 — thomassankara.net | nofi.media','["2025-02-13","2026-03-19","2027-04-22","2028-05-25","2029-06-28","2030-08-01"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_263afe72', 'Formez-vous, armez-vous de sciences jusqu''aux dents et arrachez votre patrimoine culturel.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Université Cheikh Anta Diop, Dakar — Discours à la jeunesse africaine','["2025-02-14","2026-03-20","2027-04-23","2028-05-26","2029-06-29","2030-08-02"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cef0a7dd', 'Nous devons préférer un pas avec le peuple plutôt que de faire dix pas sans lui.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio','["2025-02-15","2026-03-21","2027-04-24","2028-05-27","2029-06-30","2030-08-03"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2e229f71', 'Sans formation politique et idéologique, un militaire n''est qu''un criminel en puissance.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Wikiquote FR','["2025-02-16","2026-03-22","2027-04-25","2028-05-28","2029-07-01","2030-08-04"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5995f993', 'La connaissance du mal est une connaissance inadéquate.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie IV, Proposition LXIV, 1677','["2025-02-17","2026-03-23","2027-04-26","2028-05-29","2029-07-02","2030-08-05"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4ddd989d', 'Handle so, daß du die Menschheit sowohl in deiner Person, als in der Person eines jeden andern jederzeit zugleich als Zweck, niemals bloß als Mittel brauchst.', 'Emmanuel Kant', 'Allemand', '''Grundlegung zur Metaphysik der Sitten'', Section II, 1785','["2025-02-18","2026-03-24","2027-04-27","2028-05-30","2029-07-03","2030-08-06"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2a9c04aa', 'Lex iniusta non est lex.', 'Saint Augustin', 'Berbère/Numide (Algérien)', '''De libero arbitrio'', Livre I, Chapitre 5, ~395','["2025-02-19","2026-03-25","2027-04-28","2028-05-31","2029-07-04","2030-08-07"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_38a04f22', 'δικαιοσύνη ἀρετή ἐστιν καθ'' ἣν ἕκαστος ἔχει τὸ αὑτοῦ κατὰ τὸν νόμον.', 'Aristote', 'Grec', '''Ethica Ordine Geometrico Demonstrata à Nicomaque'', Livre V, Chapitre 1 (1129b), ~335 av. J.-C.','["2025-02-20","2026-03-26","2027-04-29","2028-06-01","2029-07-05","2030-08-08"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d9772be5', 'Ce n''est pas parce qu''une chose est juste qu''elle est légale, mais parce qu''elle est légale qu''elle est juste.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 312, 1670 (posthume)','["2025-02-21","2026-03-27","2027-04-30","2028-06-02","2029-07-06","2030-08-09"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cff522e1', 'Where there is no law, there is no freedom.', 'John Locke', 'Britannique', '''Two Treatises of Government'', §57, 1689','["2025-02-22","2026-03-28","2027-05-01","2028-06-03","2029-07-07","2030-08-10"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d06bb41e', 'Ainsi l''impérialisme, tel le chasseur de la préhistoire, tue d''abord spirituellement et culturellement l''être avant de l''éliminer physiquement.', 'Cheikh Anta Diop', 'Sénégalais', '''Alerte sous les tropiques'', Présence Africaine, 2006','["2025-02-23","2026-03-29","2027-05-02","2028-06-04","2029-07-08","2030-08-11"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_05a9c571', 'The natural equality of mankind is a fundamental principle of morality.', 'David Hume', 'Écossais', '''An Enquiry Concerning the Principles of Morals'', Section III, 1751','["2025-02-24","2026-03-30","2027-05-03","2028-06-05","2029-07-09","2030-08-12"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e7eb2350', 'If the injustice is part of the necessary friction of the machine of government, let it go.', 'Henry David Thoreau', 'Américain', '''Resistance to Civil Government (Civil Disobedience)'', 1849','["2025-02-25","2026-03-31","2027-05-04","2028-06-06","2029-07-10","2030-08-13"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_72badc89', 'Remota itaque iustitia quid sunt regna nisi magna latrocinia?', 'Saint Augustin', 'Berbère/Numide (Algérien)', '''De Civitate Dei'', Livre IV, Chapitre 4, ~413-426','["2025-02-26","2026-04-01","2027-05-05","2028-06-07","2029-07-11","2030-08-14"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_15e86d70', 'Eine Handlung hat moralischen Wert nicht wegen der Wirkungen, die sie hervorbringt, sondern weil sie aus Pflicht getan wird.', 'Emmanuel Kant', 'Allemand', '''Grundlegung zur Metaphysik der Sitten'', Section I, 1785','["2025-02-27","2026-04-02","2027-05-06","2028-06-08","2029-07-12","2030-08-15"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_eae9813f', 'Il est dangereux d''avoir raison dans des choses où les autorités établies ont tort.', 'Voltaire', 'Français', '''Catalogue des écrivains français'', 1752','["2025-02-28","2026-04-03","2027-05-07","2028-06-09","2029-07-13","2030-08-16"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1b9736d9', 'I have fought against white domination, and I have fought against black domination.', 'Nelson Mandela', 'Sud-Africain', 'Discours au Rivonia Trial, 20 avril 1964 — Nelson Mandela Foundation','["2025-03-01","2026-04-04","2027-05-08","2028-06-10","2029-07-14","2030-08-17"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ca394af2', 'La tyrannie d''un prince ne met pas un État si près de sa ruine que l''indifférence pour le bien public.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre III, Chapitre 3, 1748','["2025-03-02","2026-04-05","2027-05-09","2028-06-11","2029-07-15","2030-08-18"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d2d42353', 'L''homme libre ne pense à rien de moins qu''à la mort, et sa sagesse est une méditation non de la mort mais de la vie.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie IV, Proposition LXVII, 1677','["2025-03-03","2026-04-06","2027-05-10","2028-06-12","2029-07-16","2030-08-19"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_27a7b611', 'Un homme vertueux voudra pour les autres les mêmes biens qu''il désire pour lui-même.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie IV, Proposition XXXVII, 1677','["2025-03-04","2026-04-07","2027-05-11","2028-06-13","2029-07-17","2030-08-20"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3e89be63', 'Das Recht ist der Inbegriff der Bedingungen, unter denen die Willkür des einen mit der Willkür des andern nach einem allgemeinen Gesetze der Freiheit zusammen vereinigt werden kann.', 'Emmanuel Kant', 'Allemand', '''Metaphysik der Sitten, Rechtslehre'', Métaphysique des mœurs, §B, 1797','["2025-03-05","2026-04-08","2027-05-12","2028-06-14","2029-07-18","2030-08-21"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_36ef7fa9', 'Ceux qui ont conduit des révolutions à moitié ne font que se creuser un tombeau.', 'Louis Antoine de Saint-Just', 'Français', 'Discours à la Convention Nationale, 1793','["2025-03-06","2026-04-09","2027-05-13","2028-06-15","2029-07-19","2030-08-22"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2c4bec01', 'L''égalité des droits des femmes est une nécessité fondamentale pour le triomphe de la révolution.', 'Thomas Sankara', 'Burkinabé', '''L''émancipation des femmes et la lutte de libération de l''Afrique'', Pathfinder Press, 2001','["2025-03-07","2026-04-10","2027-05-14","2028-06-16","2029-07-20","2030-08-23"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dda34de0', 'Le bon sens est la chose du monde la mieux partagée.', 'René Descartes', 'Français', '''Discours de la méthode'', Première partie, 1637','["2025-03-08","2026-04-11","2027-05-15","2028-06-17","2029-07-21","2030-08-24"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c99435cd', 'Pour examiner la vérité, il est besoin une fois dans sa vie de mettre toutes choses en doute autant qu''il se peut.', 'René Descartes', 'Français', '''Principia Philosophiae'', Partie I, §1, 1644','["2025-03-09","2026-04-12","2027-05-16","2028-06-18","2029-07-22","2030-08-25"]',  'verified', 'tp_justice_et_egalite');
INSERT INTO topics (id, name) VALUES ('tp_courage_et_resilience', 'Courage & Résilience');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f3e3ac7c', 'Do not judge me by my successes, judge me by how many times I fell down and got back up again.', 'Nelson Mandela', 'Sud-Africain', '''Nelson Mandela By Himself'', Nelson Mandela Foundation, 2010','["2025-03-10","2026-04-13","2027-05-17","2028-06-19","2029-07-23","2030-08-26"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8a2db0e6', 'I learned that courage was not the absence of fear, but the triumph over it.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995 — Nelson Mandela Foundation','["2025-03-11","2026-04-14","2027-05-18","2028-06-20","2029-07-24","2030-08-27"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e2e3ac3c', 'Was mich nicht umbringt, macht mich stärker.', 'Friedrich Nietzsche', 'Allemand', '''Götzen-Dämmerung, oder, Wie man mit dem Hammer philosophirt'' (Le Crépuscule des idoles), §8, 1888','["2025-03-12","2026-04-15","2027-05-19","2028-06-21","2029-07-25","2030-08-28"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e9e87ad8', 'Je me suis fait une raison. Soit je finirai vieil homme quelque part, soit ce sera une fin violente. Une fois qu''on l''a accepté, ce n''est plus qu''une question de temps.', 'Thomas Sankara', 'Burkinabé', 'Babelio — ''Thomas Sankara parle'' | thomassankara.net','["2025-03-13","2026-04-16","2027-05-20","2028-06-22","2029-07-26","2030-08-29"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_49b93832', 'On peut tuer un homme mais pas ses idées.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Discours et interviews','["2025-03-14","2026-04-17","2027-05-21","2028-06-23","2029-07-27","2030-08-30"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_35612ea8', 'La Révolution démocratique et populaire a besoin d''un peuple de convaincus et non d''un peuple de vaincus.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio','["2025-03-15","2026-04-18","2027-05-22","2028-06-24","2029-07-28","2030-08-31"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_32ba7d16', 'Les révolutionnaires n''ont pas peur de leurs fautes. Ils ont le courage politique de les reconnaître publiquement.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Discours officiels','["2025-03-16","2026-04-19","2027-05-23","2028-06-25","2029-07-29","2030-09-01"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9800503f', 'After climbing a great hill, one only finds that there are many more hills to climb.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Conclusion, 1995','["2025-03-17","2026-04-20","2027-05-24","2028-06-26","2029-07-30","2030-09-02"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1b4515c5', 'Death is something inevitable. When a man has done what he considers to be his duty to his people and his country, he can rest in peace.', 'Nelson Mandela', 'Sud-Africain', 'Documentaire ''Mandela'', 1994 — Nelson Mandela Foundation','["2025-03-18","2026-04-21","2027-05-25","2028-06-27","2029-07-31","2030-09-03"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4689ab65', 'Lieber zu Grunde gehen als hassen und fürchten.', 'Friedrich Nietzsche', 'Allemand', '''Morgenröthe'', §437, 1881','["2025-03-19","2026-04-22","2027-05-26","2028-06-28","2029-08-01","2030-09-04"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_67335cb3', 'Was aus Liebe getan wird, geschieht immer jenseits von Gut und Böse.', 'Friedrich Nietzsche', 'Allemand', '''Jenseits von Gut und Böse'' (Jenseits von Gut und Böse), §153, 1886','["2025-03-20","2026-04-23","2027-05-27","2028-06-29","2029-08-02","2030-09-05"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_389aae7f', 'If you concentrate on what you don''t have, you will never, ever have enough.', 'Nelson Mandela', 'Sud-Africain', 'Conversation avec Richard Stengel, 3 mai 1993 — Nelson Mandela Foundation','["2025-03-21","2026-04-24","2027-05-28","2028-06-30","2029-08-03","2030-09-06"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b15f9393', 'Werde, der du bist.', 'Friedrich Nietzsche', 'Allemand', '''Also sprach Zarathustra'', Prologue, 1883-1885','["2025-03-22","2026-04-25","2027-05-29","2028-07-01","2029-08-04","2030-09-07"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_68d95dfb', 'Si vous voulez faire une œuvre durable, soyez patients, soyez bons, soyez humains.', 'Amadou Hampâté Bâ', 'Malien', '''Sur les traces d''Amkoullel l''enfant peul'', Actes Sud, 1991','["2025-03-23","2026-04-26","2027-05-30","2028-07-02","2029-08-05","2030-09-08"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fb574ec5', 'Seule une jeunesse mobilisée, organisée, est dangereuse — elle effraye même les bombes atomiques.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net — Babelio','["2025-03-24","2026-04-27","2027-05-31","2028-07-03","2029-08-06","2030-09-09"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_19762a54', 'Was groß ist am Menschen, das ist, daß er eine Brücke und kein Zweck ist.', 'Friedrich Nietzsche', 'Allemand', '''Also sprach Zarathustra'', Prologue §4, 1883','["2025-03-25","2026-04-28","2027-06-01","2028-07-04","2029-08-07","2030-09-10"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_48541669', 'Nemo potest personam diu ferre.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre XXVI, ~65 ap. J.-C.','["2025-03-26","2026-04-29","2027-06-02","2028-07-05","2029-08-08","2030-09-11"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e86faa2b', '知彼知己，百戰不殆。', 'Sun Tzu', 'Chinois', '''孫子兵法 (Sūnzǐ Bīngfǎ)'', Chapitre III, ~500 av. J.-C.','["2025-03-27","2026-04-30","2027-06-03","2028-07-06","2029-08-09","2030-09-12"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_16180cbe', '夫兵形象水，水之形避高而趨下。', 'Sun Tzu', 'Chinois', '''孫子兵法 (Sūnzǐ Bīngfǎ)'', Chapitre VI, ~500 av. J.-C.','["2025-03-28","2026-05-01","2027-06-04","2028-07-07","2029-08-10","2030-09-13"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fdab2e4e', 'Μὴ ζήτει τὰ γινόμενα γίνεσθαι ὡς θέλεις, ἀλλὰ θέλε τὰ γινόμενα ὡς ἔστι.', 'Épictète', 'Grec/Phrygien', '''Ἐγχειρίδιον (Enkheiridion)'' (Enchiridion), §8, ~135 ap. J.-C.','["2025-03-29","2026-05-02","2027-06-05","2028-07-08","2029-08-11","2030-09-14"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_87443039', 'Τὸ ἐμποδίζον τῇ πράξει συμπράττει αὐτῇ.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'', Livre V, §20, ~170 ap. J.-C.','["2025-03-30","2026-05-03","2027-06-06","2028-07-09","2029-08-12","2030-09-15"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_51a87742', 'Les grandes choses ne se font pas par impulsion, mais par une série de petites choses rassemblées.', 'Vincent van Gogh', 'Néerlandais', 'Lettre à son frère Théo van Gogh, 22 octobre 1882','["2025-03-31","2026-05-04","2027-06-07","2028-07-10","2029-08-13","2030-09-16"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5f457714', 'Die Größe eines Menschen bemißt sich nach dem, was er auf sich nehmen kann.', 'Friedrich Nietzsche', 'Allemand', '''Ecce Homo'', ''Pourquoi je suis si sage'', §3, 1888','["2025-04-01","2026-05-05","2027-06-08","2028-07-11","2029-08-14","2030-09-17"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c85e550f', '知彼知己，百戰不殆。', 'Sun Tzu', 'Chinois', '''孫子兵法 (Sūnzǐ Bīngfǎ)'', Chapitre III, ~500 av. J.-C.','["2025-04-02","2026-05-06","2027-06-09","2028-07-12","2029-08-15","2030-09-18"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f90a6a35', 'Magna ingenia latent.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre LXXIX, ~65 ap. J.-C.','["2025-04-03","2026-05-07","2027-06-10","2028-07-13","2029-08-16","2030-09-19"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_17e628bb', 'A tiger does not proclaim its tigritude; it pounces.', 'Wole Soyinka', 'Nigérian', 'Débat à la Conférence de Berlin, 1964','["2025-04-04","2026-05-08","2027-06-11","2028-07-14","2029-08-17","2030-09-20"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_47eae75b', 'Non quia difficilia sunt non audemus, sed quia non audemus difficilia sunt.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre CIV','["2025-04-05","2026-05-09","2027-06-12","2028-07-15","2029-08-18","2030-09-21"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_92a7e42a', 'Sapere aude! Habe Mut, dich deines eigenen Verstandes zu bedienen!', 'Emmanuel Kant', 'Allemand', '''Beantwortung der Frage: Was ist Aufklärung?'', 1784','["2025-04-06","2026-05-10","2027-06-13","2028-07-16","2029-08-19","2030-09-22"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_31098009', 'Seul celui qui tente le possible sait ce qui lui est impossible.', 'René Char', 'Français', '''Feuillets d''Hypnos'', Gallimard, 1946','["2025-04-07","2026-05-11","2027-06-14","2028-07-17","2029-08-20","2030-09-23"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_17f2ecb6', 'Gedanken ohne Inhalt sind leer, Anschauungen ohne Begriffe sind blind.', 'Emmanuel Kant', 'Allemand', '''Kritik der reinen Vernunft'', Analytique transcendantale, §1, 1781','["2025-04-08","2026-05-12","2027-06-15","2028-07-18","2029-08-21","2030-09-24"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4dad8bf0', 'Das Wahre ist das Ganze.', 'Georg Wilhelm Friedrich Hegel', 'Allemand', '''Phänomenologie des Geistes'', Préface, 1807','["2025-04-09","2026-05-13","2027-06-16","2028-07-19","2029-08-22","2030-09-25"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_37330f03', 'Πάντες ἄνθρωποι τοῦ εἰδέναι ὀρέγονται φύσει.', 'Aristote', 'Grec', '''Τὰ μετὰ τὰ φυσικά (Ta meta ta physika)'', Livre I, §1 (980a21), ~335 av. J.-C.','["2025-04-10","2026-05-14","2027-06-17","2028-07-20","2029-08-23","2030-09-26"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_eaae8088', 'Reason is, and ought only to be the slave of the passions.', 'David Hume', 'Écossais', '''A Treatise of Human Nature'', Livre II, Partie III, Section III, 1739','["2025-04-11","2026-05-15","2027-06-18","2028-07-21","2029-08-24","2030-09-27"]',  'verified', 'tp_courage_et_resilience');
INSERT INTO topics (id, name) VALUES ('tp_connaissance_et_sagesse', 'Connaissance & Sagesse');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e846bdda', 'En Afrique, quand un vieillard meurt, c''est une bibliothèque qui brûle.', 'Amadou Hampâté Bâ', 'Malien', 'Discours à l''UNESCO, Paris, 1960 — Wikiquote FR | Dicocitations','["2025-04-12","2026-05-16","2027-06-19","2028-07-22","2029-08-25","2030-09-28"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a0124d53', 'Education is the most powerful weapon which you can use to change the world.', 'Nelson Mandela', 'Sud-Africain', 'Discours au lancement de Mindset Network, 16 juillet 2003 — Nelson Mandela Foundation','["2025-04-13","2026-05-17","2027-06-20","2028-07-23","2029-08-26","2030-09-29"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7731c857', 'La facilité avec laquelle nous renonçons à notre culture ne s''explique que par notre ignorance de celle-ci.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — ''Nations nègres et culture'', Présence Africaine, 1954','["2025-04-14","2026-05-18","2027-06-21","2028-07-24","2029-08-27","2030-09-30"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e17939de', 'Μάλα γὰρ φιλοσόφου τοῦτο τὸ πάθος, τὸ θαυμάζειν.', 'Socrate', 'Grec', 'Rapporté par Platon dans ''Θεαίτητος (Theaitētos)'', 155d, ~369 av. J.-C.','["2025-04-15","2026-05-19","2027-06-22","2028-07-25","2029-08-28","2030-10-01"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dfba94ef', 'ἓν οἶδα ὅτι οὐδὲν οἶδα.', 'Socrate', 'Grec', 'Rapporté par Platon dans ''Ἀπολογία Σωκράτους (Apologia Sokratous)'', 21d, ~399 av. J.-C.','["2025-04-16","2026-05-20","2027-06-23","2028-07-26","2029-08-29","2030-10-02"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e9de1a3b', 'γνῶθι σεαυτόν.', 'Socrate', 'Grec', 'Oracle de Delphes — rapporté par Platon dans ''Ἀλκιβιάδης (Alkibiadēs)'', 124a','["2025-04-17","2026-05-21","2027-06-24","2028-07-27","2029-08-30","2030-10-03"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_111a8d31', '學而不思則罔，思而不學則殆。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre II, §15 — traduction D.C. Lau, Penguin, 1979','["2025-04-18","2026-05-22","2027-06-25","2028-07-28","2029-08-31","2030-10-04"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_29ac2655', '知之為知之，不知為不知，是知也。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre II, §17 — traduction D.C. Lau, Penguin, 1979','["2025-04-19","2026-05-23","2027-06-26","2028-07-29","2029-09-01","2030-10-05"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7a75ae90', '己所不欲，勿施於人。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre XII, §2 et Livre XV, §23 — traduction D.C. Lau','["2025-04-20","2026-05-24","2027-06-27","2028-07-30","2029-09-02","2030-10-06"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1071df4e', 'Si tu penses comme moi, tu es mon frère. Si tu ne penses pas comme moi, tu es deux fois mon frère, car tu m''ouvres un autre monde.', 'Amadou Hampâté Bâ', 'Malien', '''Amkoullel, l''enfant peul'', Actes Sud, 1991','["2025-04-21","2026-05-25","2027-06-28","2028-07-31","2029-09-03","2030-10-07"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_98e445cb', 'La beauté d''un tapis vient de la variété de ses couleurs.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 34','["2025-04-22","2026-05-26","2027-06-29","2028-08-01","2029-09-04","2030-10-08"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_86517fe6', 'La tradition transmise oralement est si précise que l''on peut reconstituer les grands événements des siècles passés.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 25','["2025-04-23","2026-05-27","2027-06-30","2028-08-02","2029-09-05","2030-10-09"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6922bf4d', 'Custom, then, is the great guide of human life.', 'David Hume', 'Écossais', '''An Enquiry Concerning Human Understanding'', Section V, 1748','["2025-04-24","2026-05-28","2027-07-01","2028-08-03","2029-09-06","2030-10-10"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fdde4ac7', 'Les Africains doivent bâtir des humanités à base d''égyptien ancien, comme l''Occident l''a fait à partir de la base gréco-latine.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954','["2025-04-25","2026-05-29","2027-07-02","2028-08-04","2029-09-07","2030-10-11"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_737c4cda', 'Nous aspirons tous au triomphe de la notion d''espèce humaine, de sorte que l''histoire particulière de chaque race s''efface devant celle de l''homme.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954','["2025-04-26","2026-05-30","2027-07-03","2028-08-05","2029-09-08","2030-10-12"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2655a1c5', 'L''Afrique doit opter pour une politique de développement scientifique ; sa vulnérabilité est la conséquence d''une déficience technique.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — ''Les fondements économiques et culturels d''un État fédéral d''Afrique noire'', Présence Africaine','["2025-04-27","2026-05-31","2027-07-04","2028-08-06","2029-09-09","2030-10-13"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_248656b2', 'La connaissance sans conscience n''est que ruine de l''âme.', 'François Rabelais', 'Français', '''La Vie de Gargantua et de Pantagruel'', Livre II, Chapitre 8, 1532','["2025-04-28","2026-06-01","2027-07-05","2028-08-07","2029-09-10","2030-10-14"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_33911e6b', 'La raison est la lumière naturelle de l''homme.', 'René Descartes', 'Français', '''Regulae ad Directionem Ingenii'', Règle I, 1628 (posthume)','["2025-04-29","2026-06-02","2027-07-06","2028-08-08","2029-09-11","2030-10-15"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c7987d4f', 'Philosopher, c''est apprendre à mourir.', 'Michel de Montaigne', 'Français', '''Essais'', Livre I, Chapitre 20, 1580','["2025-04-30","2026-06-03","2027-07-07","2028-08-09","2029-09-12","2030-10-16"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dfd9df21', 'Ignorance more frequently begets confidence than does knowledge.', 'Charles Darwin', 'Britannique', '''The Descent of Man'', John Murray, 1871, Introduction','["2025-05-01","2026-06-04","2027-07-08","2028-08-10","2029-09-13","2030-10-17"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a92aacc6', 'L''abandon de nos langues nous couperait de nos traditions et modifierait la structure même de notre esprit.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 32','["2025-05-02","2026-06-05","2027-07-09","2028-08-11","2029-09-14","2030-10-18"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0ee73099', 'En tradition africaine, la parole est sacrée car elle engage l''être total.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972','["2025-05-03","2026-06-06","2027-07-10","2028-08-12","2029-09-15","2030-10-19"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_aae28648', 'Reason is, and ought only to be the slave of the passions.', 'David Hume', 'Écossais', '''A Treatise of Human Nature'', Livre II, Partie III, §3, 1739','["2025-05-04","2026-06-07","2027-07-11","2028-08-13","2029-09-16","2030-10-20"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d61e9725', 'Ἡ εὐδαιμονία σου ἐκ τῆς ποιότητος τῶν σῶν διανοημάτων ἐξαρτᾶται.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'' (Meditations), Livre III, §9 — traduction Gregory Hays','["2025-05-05","2026-06-08","2027-07-12","2028-08-14","2029-09-17","2030-10-21"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_07bd57e0', 'Ἐπὶ σοί ἐστιν ἡ διάνοια, οὐ τὰ ἐκτός.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'' (Meditations), Livre IV, §3 — traduction Gregory Hays','["2025-05-06","2026-06-09","2027-07-13","2028-08-15","2029-09-18","2030-10-22"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e2622db8', 'Εἰ λυπεῖ σε τὸ ἐκτός, οὐ τοῦτό σε λυπεῖ, ἀλλὰ ἡ κρίσις σου περὶ αὐτοῦ.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'' (Meditations), Livre VIII, §45','["2025-05-07","2026-06-10","2027-07-14","2028-08-16","2029-09-19","2030-10-23"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_98cc800f', 'الحكمة والشريعة لا تتناقضان، فما صح في الفلسفة لا يمكن أن يكون باطلاً في الشريعة.', 'Ibn Rushd (Averroès)', 'Andalou/Marocain', '''فصل المقال (Faṣl al-Maqāl)'' (Fasl al-maqal), ~1179','["2025-05-08","2026-06-11","2027-07-15","2028-08-17","2029-09-20","2030-10-24"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a19e7695', 'العقل الإنساني قوة تسمو تدريجياً نحو المعرفة الكلية.', 'Ibn Sina (Avicenne)', 'Perse (Ouzbékistan)', '''كتاب الشفاء (Kitāb al-Shifāʾ)'', Psychologie, §1, ~1020','["2025-05-09","2026-06-12","2027-07-16","2028-08-18","2029-09-21","2030-10-25"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_da985e4b', 'Que sais-je?', 'Michel de Montaigne', 'Français', '''Essais'', Livre II, Chapitre 12 (''Apologie de Raymond Sebond''), 1580','["2025-05-10","2026-06-13","2027-07-17","2028-08-19","2029-09-22","2030-10-26"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1fb97548', 'La grandeur de l''homme est qu''il est un être de désir, d''illusions et d''espoir.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 148, 1670 (posthume)','["2025-05-11","2026-06-14","2027-07-18","2028-08-20","2029-09-23","2030-10-27"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ae66d4e8', 'Le cœur a ses raisons que la raison ne connaît point.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 277, 1670 (posthume)','["2025-05-12","2026-06-15","2027-07-19","2028-08-21","2029-09-24","2030-10-28"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2cbf784f', 'Tout notre raisonnement se réduit à céder au sentiment.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 274, 1670 (posthume)','["2025-05-13","2026-06-16","2027-07-20","2028-08-22","2029-09-25","2030-10-29"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_59d1c3c1', 'Ce que l''on conçoit bien s''énonce clairement, et les mots pour le dire arrivent aisément.', 'Nicolas Boileau', 'Français', '''L''Art poétique'', Chant I, 1674','["2025-05-14","2026-06-17","2027-07-21","2028-08-23","2029-09-26","2030-10-30"]',  'verified', 'tp_connaissance_et_sagesse');
INSERT INTO topics (id, name) VALUES ('tp_humanite_et_fraternite', 'Humanité & Fraternité');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7c5904a1', 'Ubuntu : Je suis parce que nous sommes.', 'Philosophie Ubuntu', 'Africain', 'Concept bantou ''umuntu ngumuntu ngabantu'' — diffusé internationalement par Desmond Tutu et Nelson Mandela','["2025-05-15","2026-06-18","2027-07-22","2028-08-24","2029-09-27","2030-10-31"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4f052665', 'Our freedom is incomplete without the freedom of the Palestinians.', 'Nelson Mandela', 'Sud-Africain', 'Discours à la journée de solidarité avec la Palestine — Nelson Mandela Foundation','["2025-05-16","2026-06-19","2027-07-23","2028-08-25","2029-09-28","2030-11-01"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_72ac1033', 'We must learn to live together as brothers or perish together as fools.', 'Martin Luther King', 'Américain', 'Discours ''A Choice of Two Ways'', 1961 — The King Papers, Stanford University','["2025-05-17","2026-06-20","2027-07-24","2028-08-26","2029-09-29","2030-11-02"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_017a7f8f', 'A un interlocuteur qui me demandait ce que l''Afrique pourrait apporter, j''ai répondu : ''le rire, que vous avez perdu.''', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 21-22','["2025-05-18","2026-06-21","2027-07-25","2028-08-27","2029-09-30","2030-11-03"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_56480c65', 'En Afrique traditionnelle, l''individu est inséparable de sa lignée, qui continue de vivre à travers lui.', 'Amadou Hampâté Bâ', 'Malien', '''Amkoullel, l''enfant peul'', Actes Sud, 1991','["2025-05-19","2026-06-22","2027-07-26","2028-08-28","2029-10-01","2030-11-04"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f5049ee9', 'ὁ ἄνθρωπος φύσει πολιτικὸν ζῷον.', 'Aristote', 'Grec', '''Πολιτικά (Politika)'', Livre I, §2 (''zoon politikon''), ~335 av. J.-C.','["2025-05-20","2026-06-23","2027-07-27","2028-08-29","2029-10-02","2030-11-05"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_35f8c345', 'Nous sommes tous responsables de tous.', 'Fiodor Dostoïevski', 'Russe', '''Братья Карамазовы (Brat''ya Karamazovy)'', 1880, discours du père Zosime','["2025-05-21","2026-06-24","2027-07-28","2028-08-30","2029-10-03","2030-11-06"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6925af95', 'No man is an Island, entire of itself.', 'John Donne', 'Britannique', '''Devotions upon Emergent Occasions'', 1624, Méditation XVII','["2025-05-22","2026-06-25","2027-07-29","2028-08-31","2029-10-04","2030-11-07"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fcdf4c7e', 'La tradition se préoccupe de la personne humaine en tant que multiplicité intérieure, appelée à s''ordonner et à s''unifier.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 17','["2025-05-23","2026-06-26","2027-07-30","2028-09-01","2029-10-05","2030-11-08"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9924ce69', 'Handle nur nach derjenigen Maxime, durch die du zugleich wollen kannst, daß sie ein allgemeines Gesetz werde.', 'Emmanuel Kant', 'Allemand', '''Grundlegung zur Metaphysik der Sitten'', 1785','["2025-05-24","2026-06-27","2027-07-31","2028-09-02","2029-10-06","2030-11-09"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f9d9fe83', 'Nous sommes tous liés par un destin commun sur cette petite planète.', 'John F. Kennedy', 'Américain', 'Discours à l''Université Américaine, 10 juin 1963','["2025-05-25","2026-06-28","2027-08-01","2028-09-03","2029-10-07","2030-11-10"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5c24b182', 'Amicus est tamquam alter idem.', 'Cicéron', 'Romain', '''Laelius de Amicitia'', §21, ~44 av. J.-C.','["2025-05-26","2026-06-29","2027-08-02","2028-09-04","2029-10-08","2030-11-11"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_493ccc34', 'الإنسان مدني بالطبع.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Chapitre II, §1, 1377','["2025-05-27","2026-06-30","2027-08-03","2028-09-05","2029-10-09","2030-11-12"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c9b436f0', 'Mitleid ist die Basis aller Moral.', 'Arthur Schopenhauer', 'Allemand', '''Über die Grundlage der Moral'', 1840','["2025-05-28","2026-07-01","2027-08-04","2028-09-06","2029-10-10","2030-11-13"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_142174d1', 'Les contes sont le message d''hier, destiné à demain, transmis à travers aujourd''hui.', 'Amadou Hampâté Bâ', 'Malien', 'Presses Universitaires de Bordeaux | ''Il n''y a pas de petite querelle''','["2025-05-29","2026-07-02","2027-08-05","2028-09-07","2029-10-11","2030-11-14"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2f035b06', 'Nous estimons que la dette s''analyse d''abord de par son origine. Les origines de la dette remontent aux origines du colonialisme.', 'Thomas Sankara', 'Burkinabé', 'Discours à l''OUA, Addis-Abeba, juillet 1987 — thomassankara.net | Scribd','["2025-05-30","2026-07-03","2027-08-06","2028-09-08","2029-10-12","2030-11-15"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_10b13797', 'العصبية هي أساس كل حضارة.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Livre II, §8, 1377','["2025-05-31","2026-07-04","2027-08-07","2028-09-09","2029-10-13","2030-11-16"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dc59dea9', 'A good head and a good heart are always a formidable combination.', 'Nelson Mandela', 'Sud-Africain', '''Nelson Mandela By Himself'', Nelson Mandela Foundation, 2010','["2025-06-01","2026-07-05","2027-08-08","2028-09-10","2029-10-14","2030-11-17"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8b6ee02d', 'الإنسان مدني بالطبع أي لا بد له من الاجتماع.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Livre I, §2, 1377','["2025-06-02","2026-07-06","2027-08-09","2028-09-11","2029-10-15","2030-11-18"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_26157de4', 'Homo sum: humani nihil a me alienum puto.', 'Térence', 'Carthaginois/Romain', '''Heauton Timorumenos'', Acte I, Scène 1, v. 77, 163 av. J.-C.','["2025-06-03","2026-07-07","2027-08-10","2028-09-12","2029-10-16","2030-11-19"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_de835082', 'ψυχὴ μία ἐν δυσὶ σώμασιν.', 'Aristote', 'Grec', 'Rapporté par Diogène Laërce, ''Vies des philosophes'', Livre V','["2025-06-04","2026-07-08","2027-08-11","2028-09-13","2029-10-17","2030-11-20"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_009d2789', 'Homo homini sacra res.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre XLVIII, ~65 ap. J.-C.','["2025-06-05","2026-07-09","2027-08-12","2028-09-14","2029-10-18","2030-11-21"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_84f4f133', 'ἡ εὐδαιμονία τέλος ἐστίν.', 'Aristote', 'Grec', '''Ethica Ordine Geometrico Demonstrata à Nicomaque'', Livre I, Chapitre 7 (1097a), ~335 av. J.-C.','["2025-06-06","2026-07-10","2027-08-13","2028-09-15","2029-10-19","2030-11-22"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5ae26724', 'τὰ δ'' ἔργα οὐ τοῦ τυχόντος ἀλλ'' ἀρετή ἐστιν.', 'Aristote', 'Grec', '''Ethica Ordine Geometrico Demonstrata à Nicomaque'', Livre II, Chapitre 4 (1105b), ~335 av. J.-C.','["2025-06-07","2026-07-11","2027-08-14","2028-09-16","2029-10-20","2030-11-23"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d2e6148d', 'Le fanatisme est un monstre qui ose se dire fils de la religion.', 'Voltaire', 'Français', '''Traité sur la tolérance'', Chapitre I, 1763','["2025-06-08","2026-07-12","2027-08-15","2028-09-17","2029-10-21","2030-11-24"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cdb9d0b3', 'La charité est la bienveillance universelle.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''Nouveaux essais sur l''entendement humain'', Livre II, Chapitre 28, 1704','["2025-06-09","2026-07-13","2027-08-16","2028-09-18","2029-10-22","2030-11-25"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e4479de7', '見賢思齊焉，見不賢而內自省也。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre IV, §17, ~500 av. J.-C.','["2025-06-10","2026-07-14","2027-08-17","2028-09-19","2029-10-23","2030-11-26"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_11b8b75a', '吾日三省吾身。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre I, §4, ~500 av. J.-C.','["2025-06-11","2026-07-15","2027-08-18","2028-09-20","2029-10-24","2030-11-27"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_78eb2b52', 'La chaleur humaine est supérieure à toute architecture.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 23','["2025-06-12","2026-07-16","2027-08-19","2028-09-21","2029-10-25","2030-11-28"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ebd0c8fb', 'Tous les hommes sont frères sous les rayons du même soleil.', 'Voltaire', 'Français', '''Traité sur la tolérance'', Chapitre XXII, 1763','["2025-06-13","2026-07-17","2027-08-20","2028-09-22","2029-10-26","2030-11-29"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1e62c48d', 'La société est la continuation de la famille.', 'Auguste Comte', 'Français', '''Cours de philosophie positive'', Leçon 50, 1842','["2025-06-14","2026-07-18","2027-08-21","2028-09-23","2029-10-27","2030-11-30"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_420512f6', 'No one is born hating another person because of the color of his skin.', 'Nelson Mandela', 'Sud-Africain', '''Long Walk to Freedom'', Little Brown, 1995, p. 622','["2025-06-15","2026-07-19","2027-08-22","2028-09-24","2029-10-28","2030-12-01"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_97e6a7a9', 'L''humanité se compose de plus de morts que de vivants.', 'Auguste Comte', 'Français', '''Πολιτικά (Politika) positive'', Tome II, 1852','["2025-06-16","2026-07-20","2027-08-23","2028-09-25","2029-10-29","2030-12-02"]',  'verified', 'tp_humanite_et_fraternite');
INSERT INTO topics (id, name) VALUES ('tp_pouvoir_et_politique', 'Pouvoir & Politique');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0b40b90a', 'Nous estimons que la dette s''analyse d''abord de par son origine. Les origines de la dette remontent aux origines du colonialisme.', 'Thomas Sankara', 'Burkinabé', 'Discours à l''OUA, Addis-Abeba, juillet 1987 — thomassankara.net | Scribd | Wikiquote','["2025-06-17","2026-07-21","2027-08-24","2028-09-26","2029-10-30","2030-12-03"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fdcd2e70', 'Neo-colonialism is the last stage of imperialism.', 'Kwame Nkrumah', 'Ghanéen', '''Neo-Colonialism: The Last Stage of Imperialism'', Nelson, 1965 — titre même du livre','["2025-06-18","2026-07-22","2027-08-25","2028-09-27","2029-10-31","2030-12-04"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e1cfd08d', 'Le peuple est le seul vrai souverain.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre II, 1762','["2025-06-19","2026-07-23","2027-08-26","2028-09-28","2029-11-01","2030-12-05"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c14493e2', 'government of the people, by the people, for the people.', 'Abraham Lincoln', 'Américain', 'Discours de Gettysburg, 19 novembre 1863','["2025-06-20","2026-07-24","2027-08-27","2028-09-29","2029-11-02","2030-12-06"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1065080d', 'Le colonialisme n''est pas une machine à penser, n''est pas un corps doué de raison. Il est la violence à l''état nu.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 5','["2025-06-21","2026-07-25","2027-08-28","2028-09-30","2029-11-03","2030-12-07"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f8ece076', 'Chaque génération doit découvrir sa mission, la remplir ou la trahir.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, Conclusion','["2025-06-22","2026-07-26","2027-08-29","2028-10-01","2029-11-04","2030-12-08"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8f4b09b7', 'I have fought against white domination, and I have fought against black domination.', 'Nelson Mandela', 'Sud-Africain', 'Discours au Rivonia Trial, 20 avril 1964 — Nelson Mandela Foundation','["2025-06-23","2026-07-27","2027-08-30","2028-10-02","2029-11-05","2030-12-09"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_87063fe3', 'Power tends to corrupt, and absolute power corrupts absolutely.', 'Lord Acton', 'Britannique', 'Lettre à Mandell Creighton, 5 avril 1887','["2025-06-24","2026-07-28","2027-08-31","2028-10-03","2029-11-06","2030-12-10"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_62879699', 'Africa must unite.', 'Kwame Nkrumah', 'Ghanéen', '''Africa Must Unite'', Heinemann, 1963','["2025-06-25","2026-07-29","2027-09-01","2028-10-04","2029-11-07","2030-12-11"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_27a7ae64', 'Ceux qui ont conduit des révolutions à moitié ne font que se creuser un tombeau.', 'Louis Antoine de Saint-Just', 'Français', 'Discours à la Convention Nationale, 1793','["2025-06-26","2026-07-30","2027-09-02","2028-10-05","2029-11-08","2030-12-12"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b2d0b8f5', 'L''unité africaine est la clé de la renaissance du continent.', 'Haile Selassie', 'Éthiopien', 'Discours fondateur de l''OUA, Addis-Abeba, 25 mai 1963','["2025-06-27","2026-07-31","2027-09-03","2028-10-06","2029-11-09","2030-12-13"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6a89cae3', 'La force ne crée pas le droit.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Du Contrat social'', Livre I, Chapitre 3, 1762','["2025-06-28","2026-08-01","2027-09-04","2028-10-07","2029-11-10","2030-12-14"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_35827699', 'We prefer self-government with danger to servitude in tranquility.', 'Kwame Nkrumah', 'Ghanéen', 'Discours d''indépendance du Ghana, 6 mars 1957','["2025-06-29","2026-08-02","2027-09-05","2028-10-08","2029-11-11","2030-12-15"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9140ccac', 'Long speeches, the shaking of fists and strongly worded resolutions do not bring about mass action.', 'Nelson Mandela', 'Sud-Africain', 'Discours ''No Easy Walk to Freedom'', Transvaal ANC, 21 septembre 1953 — Nelson Mandela Foundation','["2025-06-30","2026-08-03","2027-09-06","2028-10-09","2029-11-12","2030-12-16"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c7eba611', 'Ceux qui veulent exploiter l''Afrique sont les mêmes qui exploitent l''Europe.', 'Thomas Sankara', 'Burkinabé', 'samabac.com — thomassankara.net','["2025-07-01","2026-08-04","2027-09-07","2028-10-10","2029-11-13","2030-12-17"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b02b1c24', 'Vivre en révolutionnaire, mourir en révolutionnaire.', 'Thomas Sankara', 'Burkinabé', 'samabac.com — thomassankara.net','["2025-07-02","2026-08-05","2027-09-08","2028-10-11","2029-11-14","2030-12-18"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4ac4db9a', 'Il est plus sûr d''être craint qu''aimé, mais le mieux serait d''être les deux à la fois.', 'Machiavel', 'Italien', '''Il Principe'', Chapitre XVII, 1532','["2025-07-03","2026-08-06","2027-09-09","2028-10-12","2029-11-15","2030-12-19"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_eeaf7773', 'La fin justifie les moyens.', 'Machiavel', 'Italien', '''Il Principe'', Chapitre XVIII, 1532','["2025-07-04","2026-08-07","2027-09-10","2028-10-13","2029-11-16","2030-12-20"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_84ba2947', 'Quiconque veut fonder un État et lui donner des lois doit supposer les hommes méchants par nature.', 'Machiavel', 'Italien', '''Discorsi sopra la prima deca di Tito Livio'', Livre I, Chapitre 3, 1531','["2025-07-05","2026-08-08","2027-09-11","2028-10-14","2029-11-17","2030-12-21"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6c82937a', 'The accumulation of all powers, legislative, executive, and judiciary, in the same hands constitutes tyranny.', 'John Locke', 'Britannique', '''Two Treatises of Government'', §107, 1689','["2025-07-06","2026-08-09","2027-09-12","2028-10-15","2029-11-18","2030-12-22"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_031df1d2', 'Pour qu''on ne puisse abuser du pouvoir, il faut que le pouvoir arrête le pouvoir.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre XI, Chapitre 4, 1748','["2025-07-07","2026-08-10","2027-09-13","2028-10-16","2029-11-19","2030-12-23"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8859106d', 'Les lois inutiles affaiblissent les lois nécessaires.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre XXIX, Chapitre 16, 1748','["2025-07-08","2026-08-11","2027-09-14","2028-10-17","2029-11-20","2030-12-24"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_42e1945d', 'الدول تتطور من البداوة إلى الحضارة ثم تنهار.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Livre III, §1, 1377','["2025-07-09","2026-08-12","2027-09-15","2028-10-18","2029-11-21","2030-12-25"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ac94b244', 'الملك والسلطان إنما يحصلان بالعصبية.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Livre II, Chapitre 17, 1377','["2025-07-10","2026-08-13","2027-09-16","2028-10-19","2029-11-22","2030-12-26"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2f76bf2d', 'Handle nur nach der Maxime, von der du zugleich wollen kannst, daß sie allgemeines Gesetz werde.', 'Emmanuel Kant', 'Allemand', '''Zum ewigen Frieden'', Supplément II, 1795','["2025-07-11","2026-08-14","2027-09-17","2028-10-20","2029-11-23","2030-12-27"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8b0ce47e', 'La liberté politique ne consiste point à faire ce que l''on veut.', 'Montesquieu', 'Français', '''De l''esprit des lois'', Livre XI, Chapitre 3, 1748','["2025-07-12","2026-08-15","2027-09-18","2028-10-21","2029-11-24","2030-12-28"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f5c68731', 'Es ist nicht das Bewußtsein der Menschen, das ihr Sein, sondern umgekehrt ihr gesellschaftliches Sein, das ihr Bewußtsein bestimmt.', 'Karl Marx', 'Allemand', '''Zur Kritik der politischen Ökonomie'', Préface, 1859','["2025-07-13","2026-08-16","2027-09-19","2028-10-22","2029-11-25","2030-12-29"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cfb85451', 'Die Philosophen haben die Welt nur verschieden interpretiert, es kömmt darauf an, sie zu verändern.', 'Karl Marx', 'Allemand', '''Thesen über Feuerbach'', Thèse XI, 1845','["2025-07-14","2026-08-17","2027-09-20","2028-10-23","2029-11-26","2030-12-30"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a7015a51', 'Hegel bemerkt irgendwo, daß alle großen weltgeschichtlichen Tatsachen und Personen sich sozusagen zweimal ereignen. Das eine Mal als Tragödie, das andere Mal als Farce.', 'Karl Marx', 'Allemand', '''Der achtzehnte Brumaire des Louis Bonaparte'', Chapitre I, 1852','["2025-07-15","2026-08-18","2027-09-21","2028-10-24","2029-11-27","2030-12-31"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_11385caa', 'La révolution n''est pas un dîner de gala.', 'Mao Zedong', 'Chinois', '''湖南农民运动考察报告 (Húnán nóngmín yùndòng kǎochá bàogào)'', mars 1927','["2025-07-16","2026-08-19","2027-09-22","2028-10-25","2029-11-28"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c8aba153', 'Donner de bonnes lois à un peuple vicieux, c''est donner un marteau à un fou.', 'Voltaire', 'Français', '''Questions sur l''Encyclopédie'', 1770','["2025-07-17","2026-08-20","2027-09-23","2028-10-26","2029-11-29"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6f2d08e3', 'La politique est l''art du possible.', 'Otto von Bismarck', 'Allemand', 'Interview, Saint Petersburg, August 11, 1867, 11 août 1867','["2025-07-18","2026-08-21","2027-09-24","2028-10-27","2029-11-30"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ec08ab83', 'Le colonisé qui décide de réaliser ce programme est prêt à tout moment à la violence.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 6','["2025-07-19","2026-08-22","2027-09-25","2028-10-28","2029-12-01"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1c5d0141', 'Il faut d''abord oser pour ensuite pouvoir.', 'Georges Jacques Danton', 'Français', 'Discours à l''Assemblée Législative, 2 septembre 1792','["2025-07-20","2026-08-23","2027-09-26","2028-10-29","2029-12-02"]',  'verified', 'tp_pouvoir_et_politique');
INSERT INTO topics (id, name) VALUES ('tp_action_et_changement', 'Action & Changement');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0d7f3088', 'We but mirror the world. All the tendencies present in the outer world are to be found in the world of our body.', 'Mahatma Gandhi', 'Indien', '''Indian Opinion'', 1913 — Collected Works of Mahatma Gandhi, Vol. 13, Chapitre 153. NOTE: La citation populaire ''Sois le changement...'' est une paraphrase non authentifiée de ce texte.','["2025-07-21","2026-08-24","2027-09-27","2028-10-30","2029-12-03"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_37e7cf10', '千里之行，始於足下。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 64 — confirmé par Wikipedia, Taoism.net et multiple traductions académiques','["2025-07-22","2026-08-25","2027-09-28","2028-10-31","2029-12-04"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b828fbba', 'If there is no struggle, there is no progress.', 'Frederick Douglass', 'Américain', 'Discours ''West India Emancipation'', 4 août 1857 — Frederick Douglass Papers, Library of Congress','["2025-07-23","2026-08-26","2027-09-29","2028-11-01","2029-12-05"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_16ed31f1', '為學日益，為道日損。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 9, ~VIe siècle av. J.-C.','["2025-07-24","2026-08-27","2027-09-30","2028-11-02","2029-12-06"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6ac88833', 'Chaque génération doit découvrir sa mission, la remplir ou la trahir.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, Conclusion','["2025-07-25","2026-08-28","2027-10-01","2028-11-03","2029-12-07"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9b362484', '治大國若烹小鮮。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 60, ~VIe siècle av. J.-C.','["2025-07-26","2026-08-29","2027-10-02","2028-11-04","2029-12-08"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2e95d0b7', '聖人不積，既以為人己愈有。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 81, ~VIe siècle av. J.-C.','["2025-07-27","2026-08-30","2027-10-03","2028-11-05","2029-12-09"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0eabce7b', 'La révolution n''est pas un dîner de gala.', 'Mao Zedong', 'Chinois', '''湖南农民运动考察报告 (Húnán nóngmín yùndòng kǎochá bàogào)'', mars 1927','["2025-07-28","2026-08-31","2027-10-04","2028-11-06","2029-12-10"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b03bf429', 'The struggle is my life. I will continue fighting for freedom until the end of my days.', 'Nelson Mandela', 'Sud-Africain', 'Déclaration de Johannesburg, 26 juin 1961 — Nelson Mandela Foundation','["2025-07-29","2026-09-01","2027-10-05","2028-11-07","2029-12-11"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b0f27705', '君子欲訥於言而敏於行。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre IV, §24, ~500 av. J.-C.','["2025-07-30","2026-09-02","2027-10-06","2028-11-08","2029-12-12"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c9e18216', 'Les grandes choses ne se font pas par impulsion, mais par une série de petites choses rassemblées.', 'Vincent van Gogh', 'Néerlandais', 'Lettre à son frère Théo van Gogh, 22 octobre 1882 — Van Gogh Museum Archive','["2025-07-31","2026-09-03","2027-10-07","2028-11-09","2029-12-13"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b7ee45e1', '不戰而屈人之兵，善之善者也。', 'Sun Tzu', 'Chinois', '''孫子兵法 (Sūnzǐ Bīngfǎ)'', Chapitre III, ~500 av. J.-C.','["2025-08-01","2026-09-04","2027-10-08","2028-11-10","2029-12-14"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_60dc9351', 'La libération de la femme est une nécessité fondamentale pour le triomphe de la révolution.', 'Thomas Sankara', 'Burkinabé', 'Discours 8 mars 1987 — thomassankara.net','["2025-08-02","2026-09-05","2027-10-09","2028-11-11","2029-12-15"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_012c300f', '兵者，詭道也。', 'Sun Tzu', 'Chinois', '''孫子兵法 (Sūnzǐ Bīngfǎ)'', Chapitre I, ~500 av. J.-C.','["2025-08-03","2026-09-06","2027-10-10","2028-11-12","2029-12-16"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c521b041', 'Il faut d''abord oser pour ensuite pouvoir.', 'Georges Jacques Danton', 'Français', 'Discours à l''Assemblée Législative, 2 septembre 1792','["2025-08-04","2026-09-07","2027-10-11","2028-11-13","2029-12-17"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_99627920', 'L''imagination est plus importante que le savoir.', 'Albert Einstein', 'Allemand/Américain', '''What Life Means to Einstein'', Saturday Evening Post, 26 octobre 1929','["2025-08-05","2026-09-08","2027-10-12","2028-11-14","2029-12-18"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_32ca8530', 'Seul celui qui tente le possible sait ce qui lui est impossible.', 'René Char', 'Français', '''Feuillets d''Hypnos'', Gallimard, 1946','["2025-08-06","2026-09-09","2027-10-13","2028-11-15","2029-12-19"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ea145818', 'Ὁ ἄσκοπος βίος οὐ βίος.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'', Livre VI, §17, ~170 ap. J.-C.','["2025-08-07","2026-09-10","2027-10-14","2028-11-16","2029-12-20"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a06b0d80', 'Le présent est ce qui se fait, non ce qui est fait.', 'Henri Bergson', 'Français', '''Matière et mémoire'', PUF, 1896, Chapitre IV','["2025-08-08","2026-09-11","2027-10-15","2028-11-17","2029-12-21"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1cf4cd22', 'الدول كالأشخاص لها أعمار.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Livre III, §12, 1377','["2025-08-09","2026-09-12","2027-10-16","2028-11-18","2029-12-22"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1385fe4b', 'Es ist nicht das Bewußtsein der Menschen, das ihr Sein, sondern umgekehrt ihr gesellschaftliches Sein, das ihr Bewußtsein bestimmt.', 'Karl Marx', 'Allemand', '''Zur Kritik der politischen Ökonomie'', Préface, 1859','["2025-08-10","2026-09-13","2027-10-17","2028-11-19","2029-12-23"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_79a2a23c', 'Education makes the greatest difference between men.', 'John Locke', 'Britannique', '''Some Thoughts Concerning Education'', §1, 1693','["2025-08-11","2026-09-14","2027-10-18","2028-11-20","2029-12-24"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1f83e673', 'Literature is the conscience of a nation.', 'Wole Soyinka', 'Nigérian', 'Nobel Lecture de Littérature, Stockholm, 8 décembre 1986','["2025-08-12","2026-09-15","2027-10-19","2028-11-21","2029-12-25"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9ae4888b', 'πολεμοῦμεν ἵνα εἰρήνην ἄγωμεν.', 'Aristote', 'Grec', '''Ethica Ordine Geometrico Demonstrata à Nicomaque'', Livre X, Chapitre 7 (1177b), ~335 av. J.-C.','["2025-08-13","2026-09-16","2027-10-20","2028-11-22","2029-12-26"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7795a3ed', 'the condition of man... is a condition of war of everyone against everyone.', 'Thomas Hobbes', 'Britannique', '''Leviathan'', Partie I, Chapitre 13, 1651','["2025-08-14","2026-09-17","2027-10-21","2028-11-23","2029-12-27"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a5fd4db0', 'the life of man, solitary, poor, nasty, brutish, and short.', 'Thomas Hobbes', 'Britannique', '''Leviathan'', Partie I, Chapitre 13, 1651','["2025-08-15","2026-09-18","2027-10-22","2028-11-24","2029-12-28"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fb0d736f', 'Those who cannot remember the past are condemned to repeat it.', 'George Santayana', 'Espagnol/Américain', '''The Life of Reason'', Vol. I, Chapitre XII, 1905','["2025-08-16","2026-09-19","2027-10-23","2028-11-25","2029-12-29"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4109f348', 'Les révolutions ne se font pas avec des fleurs.', 'Lénine', 'Russe', '''Что делать? (Chto delat''?)'', 1902','["2025-08-17","2026-09-20","2027-10-24","2028-11-26","2029-12-30"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fed877ed', 'Parler est d''argent, se taire est d''or.', 'Thomas Carlyle', 'Écossais', '''Sartor Resartus'', Livre III, Chapitre III, 1833-34','["2025-08-18","2026-09-21","2027-10-25","2028-11-27","2029-12-31"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1dc43cc9', '溫故而知新，可以為師矣。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre VII, §1, ~500 av. J.-C.','["2025-08-19","2026-09-22","2027-10-26","2028-11-28","2030-01-01"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6620731f', 'Dimidium facti qui coepit habet.', 'Ausone', 'Romain/Gaulois', '''Epigrammata'', IV, ~400 ap. J.-C.','["2025-08-20","2026-09-23","2027-10-27","2028-11-29","2030-01-02"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cc9a5cd0', '譬如為山，未成一簣，止，吾止也。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre IX, §23, ~500 av. J.-C.','["2025-08-21","2026-09-24","2027-10-28","2028-11-30","2030-01-03"]',  'verified', 'tp_action_et_changement');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8b00dfb5', 'Le temps ne respecte pas ce qui se fait sans lui.', 'Aimé Césaire', 'Martiniquais', '''Cahier d''un retour au pays natal'', Présence Africaine, 1939','["2025-08-22","2026-09-25","2027-10-29","2028-12-01","2030-01-04"]',  'verified', 'tp_action_et_changement');
INSERT INTO topics (id, name) VALUES ('tp_identite_et_culture', 'Identité & Culture');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a6bd83ae', 'La négation de l''histoire africaine est le meurtre culturel de l''Afrique.', 'Cheikh Anta Diop', 'Sénégalais', '''Civilisation ou Barbarie'', Présence Africaine, Paris, 1981, p. 10','["2025-08-23","2026-09-26","2027-10-30","2028-12-02","2030-01-05"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8e620c12', 'La tradition orale africaine est d''une rigueur que peu de civilisations écrites peuvent égaler.', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 25','["2025-08-24","2026-09-27","2027-10-31","2028-12-03","2030-01-06"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ad4e313d', 'Le poison culturel inoculé dès la plus tendre enfance est devenu partie intégrante de notre substance.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — Discours à la jeunesse africaine','["2025-08-25","2026-09-28","2027-11-01","2028-12-04","2030-01-07"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_46f6b582', 'The choice of language, and the use to which language is put, is central to a people''s definition of themselves.', 'Ngugi wa Thiong''o', 'Kenyan', '''Decolonising the Mind: The Politics of Language in African Literature: The Politics of Language in African Literature'', James Currey, 1986','["2025-08-26","2026-09-29","2027-11-02","2028-12-05","2030-01-08"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7d3da8f4', 'Who controls the past controls the future. Who controls the present controls the past.', 'George Orwell', 'Britannique', '''1984'', Secker & Warburg, 1949 — ''Celui qui contrôle le passé contrôle le futur''','["2025-08-27","2026-09-30","2027-11-03","2028-12-06","2030-01-09"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cbb8c67c', 'L''identité n''est pas donnée une fois pour toutes : elle se construit et se reconstruit.', 'Amin Maalouf', 'Libanais/Français', '''Les Identités meurtrières'', Grasset, 1998','["2025-08-28","2026-10-01","2027-11-04","2028-12-07","2030-01-10"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_102e9b9a', 'The single story creates stereotypes, and the problem with stereotypes is not that they are untrue, but that they are incomplete.', 'Chimamanda Ngozi Adichie', 'Nigériane', 'TED Talk ''The Danger of a Single Story'', TEDGlobal, 2009','["2025-08-29","2026-10-02","2027-11-05","2028-12-08","2030-01-11"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d8ab49c1', 'Die Sprache ist das Haus des Seins.', 'Martin Heidegger', 'Allemand', '''Brief über den Humanismus'', 1947','["2025-08-30","2026-10-03","2027-11-06","2028-12-09","2030-01-12"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7e7bc9fe', 'Was wir sind, hängt davon ab, was wir gewesen sind.', 'Wilhelm Dilthey', 'Allemand', '''Einleitung in die Geisteswissenschaften'', 1883','["2025-08-31","2026-10-04","2027-11-07","2028-12-10","2030-01-13"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4ea3591d', 'Was vernünftig ist, das ist wirklich; und was wirklich ist, das ist vernünftig.', 'Georg Wilhelm Friedrich Hegel', 'Allemand', '''Grundlinien der Philosophie des Rechts'', Préface, 1820','["2025-09-01","2026-10-05","2027-11-08","2028-12-11","2030-01-14"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ef765d38', 'L''identité narrative est cette identité que nous construisons en racontant notre propre histoire.', 'Paul Ricoeur', 'Français', '''Soi-même comme un autre'', Seuil, 1990, p. 174','["2025-09-02","2026-10-06","2027-11-09","2028-12-12","2030-01-15"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1b474b82', 'Raconter, c''est déjà expliquer.', 'Paul Ricoeur', 'Français', '''Temps et récit'', Tome I, Seuil, 1983','["2025-09-03","2026-10-07","2027-11-10","2028-12-13","2030-01-16"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_731dfb9e', 'L''Égypte ancienne est à l''Afrique noire ce que la Grèce et Rome sont à l''Occident.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954, p. 14','["2025-09-04","2026-10-08","2027-11-11","2028-12-14","2030-01-17"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2f2cc801', 'Ce que l''on nomme le ''miracle grec'' est en réalité le miracle africain transmis à la Grèce.', 'Cheikh Anta Diop', 'Sénégalais', '''Civilisation ou Barbarie'', Présence Africaine, 1981, p. 251','["2025-09-05","2026-10-09","2027-11-12","2028-12-15","2030-01-18"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_33d64d5f', 'Imitation is suicide.', 'Ralph Waldo Emerson', 'Américain', '''Self-Reliance'', Essays or Counsels, Civil and Moral: First Series, 1841','["2025-09-06","2026-10-10","2027-11-13","2028-12-16","2030-01-19"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4f7b3dc3', 'What you are speaks so loudly that I cannot hear what you say.', 'Ralph Waldo Emerson', 'Américain', '''Letters and Social Aims'', 1876','["2025-09-07","2026-10-11","2027-11-14","2028-12-17","2030-01-20"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a20fecdb', 'Chaque homme porte la forme entière de l''humaine condition.', 'Michel de Montaigne', 'Français', '''Essais'', Livre III, Chapitre 2, 1588','["2025-09-08","2026-10-12","2027-11-15","2028-12-18","2030-01-21"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_679c88c6', 'Ma bouche sera la bouche des malheurs qui n''ont point de bouche, ma voix la liberté de celles qui s''affaissent au cachot du désespoir.', 'Aimé Césaire', 'Martiniquais', '''Cahier d''un retour au pays natal'', Présence Africaine, 1939','["2025-09-09","2026-10-13","2027-11-16","2028-12-19","2030-01-22"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7f1522d7', 'L''Algérienne, en combattant pour la révolution, s''est aussi battue pour sa propre libération.', 'Frantz Fanon', 'Martiniquais', '''L''An V de la révolution algérienne'', Maspero, 1959, p. 38','["2025-09-10","2026-10-14","2027-11-17","2028-12-20","2030-01-23"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1a6f3373', 'Les langues africaines sont assez riches pour exprimer la pensée scientifique moderne.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Dakar — Discours sur les langues africaines, 1977','["2025-09-11","2026-10-15","2027-11-18","2028-12-21","2030-01-24"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d3bde305', 'Formez-vous, armez-vous de sciences jusqu''aux dents, et arrachez votre patrimoine culturel.', 'Cheikh Anta Diop', 'Sénégalais', 'IFAN Université Cheikh Anta Diop — Discours à la jeunesse africaine, Dakar','["2025-09-12","2026-10-16","2027-11-19","2028-12-22","2030-01-25"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_edf205c9', 'L''Egypte est nègre dans ses origines.', 'Cheikh Anta Diop', 'Sénégalais', '''Nations nègres et culture'', Présence Africaine, 1954, p. 33','["2025-09-13","2026-10-17","2027-11-20","2028-12-23","2030-01-26"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dc18002c', 'Ma bouche sera la bouche des malheurs qui n''ont point de bouche.', 'Aimé Césaire', 'Martiniquais', '''Cahier d''un retour au pays natal'', Présence Africaine, 1939','["2025-09-14","2026-10-18","2027-11-21","2028-12-24","2030-01-27"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d1ced8c3', 'The Negro is the only American who has not yet been able to be accepted as what he is.', 'James Baldwin', 'Américain', '''The Fire Next Time'', Dial Press, 1963, p. 91','["2025-09-15","2026-10-19","2027-11-22","2028-12-25","2030-01-28"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_106f7817', 'On ne nait pas avec une identité; on la construit.', 'Paul Ricoeur', 'Français', '''Soi-même comme un autre'', Seuil, 1990, p. 140','["2025-09-16","2026-10-20","2027-11-23","2028-12-26","2030-01-29"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_43daf894', 'What you are speaks so loudly that I cannot hear what you say.', 'Ralph Waldo Emerson', 'Américain', '''Letters and Social Aims'', 1876','["2025-09-17","2026-10-21","2027-11-24","2028-12-27","2030-01-30"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c4ed182b', 'No culture can live if it attempts to be exclusive.', 'Mahatma Gandhi', 'Indien', '''Harijan'', 20 juillet 1935 — Collected Works of Mahatma Gandhi, Vol. 61','["2025-09-18","2026-10-22","2027-11-25","2028-12-28","2030-01-31"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_281e5f6f', 'L''histoire est un prophète qui regarde en arrière.', 'Eduardo Galeano', 'Uruguayen', '''Las venas abiertas de América Latina'', 1971','["2025-09-19","2026-10-23","2027-11-26","2028-12-29","2030-02-01"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4c9a4f2f', 'To write in African languages was to restore the history and cultures of Africa.', 'Ngugi wa Thiong''o', 'Kenyan', '''Decolonising the Mind: The Politics of Language in African Literature'', James Currey, 1986, p. 4','["2025-09-20","2026-10-24","2027-11-27","2028-12-30","2030-02-02"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_56ba152a', 'The domination of a people''s language by the languages of the colonizing nations was crucial to the domination of the mental universe of the colonized.', 'Ngugi wa Thiong''o', 'Kenyan', '''Decolonising the Mind: The Politics of Language in African Literature'', James Currey, 1986, p. 9','["2025-09-21","2026-10-25","2027-11-28","2028-12-31","2030-02-03"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f2907f4c', 'If you talk to a man in a language he understands, that goes to his head. If you talk to him in his language, that goes to his heart.', 'Nelson Mandela', 'Sud-Africain', 'Nelson Mandela Foundation — ''Nelson Mandela By Himself'', 2010','["2025-09-22","2026-10-26","2027-11-29","2029-01-01","2030-02-04"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_84adf0f2', 'La culture est la façon dont un peuple répond aux défis de son existence.', 'Aimé Césaire', 'Martiniquais', '''Discours sur la négritude'', Miami, 26 février 1987','["2025-09-23","2026-10-27","2027-11-30","2029-01-02","2030-02-05"]',  'verified', 'tp_identite_et_culture');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d3957b1e', 'L''impérialisme a laissé dans nos mentalités des germes de la mort lente.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 311','["2025-09-24","2026-10-28","2027-12-01","2029-01-03","2030-02-06"]',  'verified', 'tp_identite_et_culture');
INSERT INTO topics (id, name) VALUES ('tp_existence_et_mort', 'Existence & Mort');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c19af031', 'Il faut imaginer Sisyphe heureux.', 'Albert Camus', 'Français/Algérien', '''Le Mythe de Sisyphe'', Gallimard, 1942 — dernière phrase','["2025-09-25","2026-10-29","2027-12-02","2029-01-04","2030-02-07"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e42735ce', 'L''existence précède l''essence.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945','["2025-09-26","2026-10-30","2027-12-03","2029-01-05","2030-02-08"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_713b13ac', 'Cogito, ergo sum.', 'René Descartes', 'Français', '''Discours de la méthode'', 1637, IVe partie ; aussi dans ''Méditations métaphysiques'', 1641','["2025-09-27","2026-10-31","2027-12-04","2029-01-06","2030-02-09"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3cd51186', 'Les morts ne sont pas morts. Ils sont dans l''arbre qui frémit, dans le bois qui gémit.', 'Birago Diop', 'Sénégalais', '''Souffles'', in ''Leurres et Lueurs'', Présence Africaine, 1960','["2025-09-28","2026-11-01","2027-12-05","2029-01-07","2030-02-10"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c3da2ce0', 'Je me suis fait une raison. Soit je finirai vieil homme quelque part, soit ce sera une fin violente.', 'Thomas Sankara', 'Burkinabé', 'Babelio — thomassankara.net | Scribd','["2025-09-29","2026-11-02","2027-12-06","2029-01-08","2030-02-11"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_88382bc6', 'Death is something inevitable. When a man has done what he considers to be his duty to his people and his country, he can rest in peace.', 'Nelson Mandela', 'Sud-Africain', 'Documentaire ''Mandela'', 1994 — Nelson Mandela Foundation','["2025-09-30","2026-11-03","2027-12-07","2029-01-09","2030-02-12"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8deb0d77', 'Ὁ θάνατος οὐδὲν πρὸς ἡμᾶς· ὅτε μὲν ἡμεῖς ἐσμεν, ὁ θάνατος οὐ πάρεστιν· ὅτε δὲ ὁ θάνατος πάρεστιν, τότε ἡμεῖς οὐκ ἐσμέν.', 'Épicure', 'Grec', '''Ἐπιστολὴ πρὸς Μενοικέα (Epistolē pros Menoikea)'', ~300 av. J.-C.','["2025-10-01","2026-11-04","2027-12-08","2029-01-10","2030-02-13"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_315edb8b', 'Ὁ βίος βραχύς, ἡ δὲ τέχνη μακρή.', 'Hippocrate', 'Grec', '''Ἀφορισμοί (Aforismoi)'', §1, ~400 av. J.-C.','["2025-10-02","2026-11-05","2027-12-09","2029-01-11","2030-02-14"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5e49e312', 'L''homme n''est qu''un roseau, le plus faible de la nature ; mais c''est un roseau pensant.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 200, 1670 (posthume)','["2025-10-03","2026-11-06","2027-12-10","2029-01-12","2030-02-15"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8abeebb9', 'Non est ad astra mollis e terris via. / Non quia difficilia sunt non audemus, sed quia non audemus difficilia sunt.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre CIV','["2025-10-04","2026-11-07","2027-12-11","2029-01-13","2030-02-16"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2ad74579', 'Ἡ εὐδαιμονία σου ἐκ τῆς ποιότητος τῶν σῶν διανοημάτων ἐξαρτᾶται.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'' (Meditations), Livre III, §9 — traduction Gregory Hays','["2025-10-05","2026-11-08","2027-12-12","2029-01-14","2030-02-17"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d4361baf', 'ὁ φιλόσοφος μελετᾷ ἀποθνῄσκειν.', 'Platon', 'Grec', '''Φαίδων (Phaidōn)'', 64a, ~380 av. J.-C.','["2025-10-06","2026-11-09","2027-12-13","2029-01-15","2030-02-18"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9b6c48d7', 'L''homme sage vit autant qu''il doit, non autant qu''il peut.', 'Michel de Montaigne', 'Français', '''Essais'', Livre I, Chapitre 20, 1580','["2025-10-07","2026-11-10","2027-12-14","2029-01-16","2030-02-19"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_100b7c28', 'I never think of the time I have lost. I just carry out my programme.', 'Nelson Mandela', 'Sud-Africain', 'Conversation avec Richard Stengel, 3 mai 1993 — Nelson Mandela Foundation','["2025-10-08","2026-11-11","2027-12-15","2029-01-17","2030-02-20"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a4517f90', 'Μίμνησο ὡς τάχα οὐδὲ σύ, οὐδὲ ὁ δεῖνα ἔσται.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'', Livre II, §14 — traduction Gregory Hays','["2025-10-09","2026-11-12","2027-12-16","2029-01-18","2030-02-21"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2bfad6ec', 'Die Welt ist meine Vorstellung.', 'Arthur Schopenhauer', 'Allemand', '''Die Welt als Wille und Vorstellung'', Vol. I, §1, 1818','["2025-10-10","2026-11-13","2027-12-17","2029-01-19","2030-02-22"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_aec84672', 'Das Leben pendelt wie ein Pendulum hin und her zwischen Schmerz und Langeweile.', 'Arthur Schopenhauer', 'Allemand', '''Die Welt als Wille und Vorstellung'', Vol. I, §57, 1818','["2025-10-11","2026-11-14","2027-12-18","2029-01-20","2030-02-23"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5d0b5fe0', 'Worüber man nicht sprechen kann, darüber muß man schweigen.', 'Ludwig Wittgenstein', 'Autrichien/Britannique', '''Logisch-Philosophische Abhandlung'', Proposition 7, 1921','["2025-10-12","2026-11-15","2027-12-19","2029-01-21","2030-02-24"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e0efd849', 'Der Tod ist kein Ereignis des Lebens.', 'Ludwig Wittgenstein', 'Autrichien/Britannique', '''Logisch-Philosophische Abhandlung'', Proposition 6.4311, 1921','["2025-10-13","2026-11-16","2027-12-20","2029-01-22","2030-02-25"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_31ba2ae1', '昔者莊周夢為胡蝶，栩栩然胡蝶也。', 'Zhuangzi', 'Chinois', '''莊子 (Zhuāngzǐ)'', Chapitre II (''Sur l''égalité des choses''), ~300 av. J.-C.','["2025-10-14","2026-11-17","2027-12-21","2029-01-23","2030-02-26"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b1aa17f3', 'L''enfer, c''est les autres.', 'Jean-Paul Sartre', 'Français', '''Huis clos'', Gallimard, 1944, Scène V','["2025-10-15","2026-11-18","2027-12-22","2029-01-24","2030-02-27"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_537bb2ec', 'Il n''y a qu''un problème philosophique vraiment sérieux : c''est le suicide.', 'Albert Camus', 'Français/Algérien', '''Le Mythe de Sisyphe'', Gallimard, 1942, p. 15','["2025-10-16","2026-11-19","2027-12-23","2029-01-25","2030-02-28"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cf54c73c', 'Gott ist tot! Gott bleibt tot! Und wir haben ihn getötet!', 'Friedrich Nietzsche', 'Allemand', '''Die fröhliche Wissenschaft'', §125, 1882','["2025-10-17","2026-11-20","2027-12-24","2029-01-26","2030-03-01"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_18583598', 'Man muß noch Chaos in sich haben, um einen tanzenden Stern gebären zu können.', 'Friedrich Nietzsche', 'Allemand', '''Also sprach Zarathustra'', Prologue, §5, 1883','["2025-10-18","2026-11-21","2027-12-25","2029-01-27","2030-03-02"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_149a2122', 'Ce que tu n''as pas en toi, tu ne peux pas le donner.', 'Amadou Hampâté Bâ', 'Malien', '''Amkoullel, l''enfant peul'', Actes Sud, 1991','["2025-10-19","2026-11-22","2027-12-26","2029-01-28","2030-03-03"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7ca58c7e', 'Dum differtur vita transcurrit.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre I, ~65 ap. J.-C.','["2025-10-20","2026-11-23","2027-12-27","2029-01-29","2030-03-04"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_01058613', 'Ce que tu es maintenant est ce que tu feras de toi.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945','["2025-10-21","2026-11-24","2027-12-28","2029-01-30","2030-03-05"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4a296ab4', 'Παῦσαι ποτε τὸ περὶ τοῦ ποῖός τις ἄνθρωπος ἀγαθός ἐστι διαλέγεσθαι. Ἀλλὰ εἶναι.', 'Marc Aurèle', 'Romain', '''Τὰ εἰς ἑαυτόν (Ta eis heauton)'' (Meditations), Livre X, §16 — traduction Gregory Hays','["2025-10-22","2026-11-25","2027-12-29","2029-01-31","2030-03-06"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9e4acb02', 'L''être précède le néant; le néant vient après.', 'Jean-Paul Sartre', 'Français', '''L''être et le néant'', Gallimard, 1943, Introduction','["2025-10-23","2026-11-26","2027-12-30","2029-02-01","2030-03-07"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_26b24898', 'L''existence précède l''essence, ce qui signifie que l''homme doit d''abord exister pour ensuite se définir.', 'Jean-Paul Sartre', 'Français', '''L''existentialisme est un humanisme'', Nagel, 1945','["2025-10-24","2026-11-27","2027-12-31","2029-02-02","2030-03-08"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0f7a34a5', 'On n''est jamais aussi libre que quand on a admis qu''on allait mourir.', 'Albert Camus', 'Français/Algérien', '''L''Homme révolté'', Gallimard, 1951','["2025-10-25","2026-11-28","2028-01-01","2029-02-03","2030-03-09"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5071bd26', 'الموت حق على كل إنسان.', 'Ibn Khaldoun', 'Tunisien', '''المقدّمة (Al-Muqaddimah)'', Livre III, §15, 1377','["2025-10-26","2026-11-29","2028-01-02","2029-02-04","2030-03-10"]',  'verified', 'tp_existence_et_mort');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_20a84883', 'Un seul être vous manque, et tout est dépeuplé.', 'Alphonse de Lamartine', 'Français', '''L''Isolement'', in ''Méditations poétiques'', 1820','["2025-10-27","2026-11-30","2028-01-03","2029-02-05","2030-03-11"]',  'verified', 'tp_existence_et_mort');
INSERT INTO topics (id, name) VALUES ('tp_femme_et_emancipation', 'Femme & Émancipation');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a16a4200', 'Il n''y a pas de révolution sociale véritable que lorsque la femme est libérée.', 'Thomas Sankara', 'Burkinabé', '''L''émancipation des femmes et la lutte de libération de l''Afrique'', Pathfinder Press, 2001, p. 45','["2025-10-28","2026-12-01","2028-01-04","2029-02-06","2030-03-12"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4400f8c1', 'La source intarissable de toutes les victoires se trouve entre les mains de la femme.', 'Thomas Sankara', 'Burkinabé', '''La révolution ne peut aboutir sans l''émancipation des femmes'', 4 octobre 1984 — Wikiquote FR','["2025-10-29","2026-12-02","2028-01-05","2029-02-07","2030-03-13"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3ec7e50d', 'Nous ne parlons pas de l''émancipation des femmes comme d''un acte de charité. C''est une nécessité fondamentale pour le triomphe de la révolution.', 'Thomas Sankara', 'Burkinabé', 'nofi.media | thomassankara.net | Pathfinder Press, 2001','["2025-10-30","2026-12-03","2028-01-06","2029-02-08","2030-03-14"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9310a9a5', 'L''inégalité ne peut être supprimée que par une nouvelle société où hommes et femmes jouiront de droits égaux.', 'Thomas Sankara', 'Burkinabé', 'Discours 8 mars 1987 — thomassankara.net | nofi.media','["2025-10-31","2026-12-04","2028-01-07","2029-02-09","2030-03-15"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fc6d79c9', 'Mères, sœurs, compagnes : il n''y a point d''homme fier tant qu''il n''y a point de femme à côté de lui.', 'Thomas Sankara', 'Burkinabé', '''La révolution ne peut aboutir sans l''émancipation des femmes'' — Wikiquote FR','["2025-11-01","2026-12-05","2028-01-08","2029-02-10","2030-03-16"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2e5905f6', 'On ne naît pas femme, on le devient.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Gallimard, 1949, Tome II, Chapitre 1','["2025-11-02","2026-12-06","2028-01-09","2029-02-11","2030-03-17"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_37e500e0', 'We should all be feminists.', 'Chimamanda Ngozi Adichie', 'Nigériane', 'TEDx Talk ''We Should All Be Feminists'', 2012 — publié en livre chez Vintage, 2014','["2025-11-03","2026-12-07","2028-01-10","2029-02-12","2030-03-18"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_705c7b46', 'I am not free while any woman is unfree, even when her chains are very different from my own.', 'Audre Lorde', 'Américaine', '''The Master''s Tools Will Never Dismantle the Master''s House'', 1984 — ''Sister Outsider'', Crossing Press','["2025-11-04","2026-12-08","2028-01-11","2029-02-13","2030-03-19"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c538b63a', 'Peace cannot be achieved without the full and complete participation of women.', 'Leymah Gbowee', 'Libérienne', 'Discours — Prix Nobel de la Paix, Oslo, 10 décembre 2011','["2025-11-05","2026-12-09","2028-01-12","2029-02-14","2030-03-20"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3794627f', 'La femme est l''avenir de l''homme.', 'Louis Aragon', 'Français', '''Le Fou d''Elsa'', Gallimard, 1963','["2025-11-06","2026-12-10","2028-01-13","2029-02-15","2030-03-21"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_692047b2', 'The principle which regulates the existing social relations between the two sexes—the legal subordination of one sex to the other—is wrong in itself.', 'John Stuart Mill', 'Britannique', '''The Subjection of Women'', Chapitre I, 1869','["2025-11-07","2026-12-11","2028-01-14","2029-02-16","2030-03-22"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dab43aec', 'The legal subordination of one sex to the other is wrong in itself.', 'John Stuart Mill', 'Britannique', '''The Subjection of Women'', Chapitre I, 1869','["2025-11-08","2026-12-12","2028-01-15","2029-02-17","2030-03-23"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_aae713f4', 'Aucune société ne peut s''émanciper sans l''émancipation des femmes.', 'Friedrich Engels', 'Allemand', '''Der Ursprung der Familie, des Privateigenthums und des Staats'', Chapitre II, 1884','["2025-11-09","2026-12-13","2028-01-16","2029-02-18","2030-03-24"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5d62881a', 'On ne naît pas femme : on le devient. Aucun destin biologique ne définit la figure que revêt la femelle humaine au sein de la société.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Tome II, Gallimard, 1949, p. 13','["2025-11-10","2026-12-14","2028-01-17","2029-02-19","2030-03-25"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_e755c288', 'Quand les femmes s''éveillent politiquement, elles sont les plus ardentes militantes.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Tome I, Gallimard, 1949, p. 23','["2025-11-11","2026-12-15","2028-01-18","2029-02-20","2030-03-26"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_718ccfea', 'I measure the courage of a society by the treatment it reserves for its women.', 'Wole Soyinka', 'Nigérian', 'Nobel Lecture de Littérature, Stockholm, 8 décembre 1986','["2025-11-12","2026-12-16","2028-01-19","2029-02-21","2030-03-27"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_de023153', 'L''émancipation des femmes n''est pas une concession, c''est une révolution.', 'Aimé Césaire', 'Martiniquais', '''Discours sur la négritude'', Miami, 26 février 1987','["2025-11-13","2026-12-17","2028-01-20","2029-02-22","2030-03-28"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8b2b4625', 'Pour nommer le monde à partir de sa propre expérience, la femme doit inventer un nouveau langage.', 'Hélène Cixous', 'Française/Algérienne', '''Le Rire de la Méduse'', L''Arc, n°61, 1975','["2025-11-14","2026-12-18","2028-01-21","2029-02-23","2030-03-29"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a7b4485d', 'La femme africaine a porté deux fois le poids de l''histoire : coloniale et patriarcale.', 'Frantz Fanon', 'Martiniquais', '''Les Damnés de la Terre'', Maspero, 1961, p. 218','["2025-11-15","2026-12-19","2028-01-22","2029-02-24","2030-03-30"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_875ff227', 'Every man has a property in his own person.', 'John Locke', 'Britannique', '''Two Treatises of Government'', §27, 1689','["2025-11-16","2026-12-20","2028-01-23","2029-02-25","2030-03-31"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_162dd726', 'Écrire, c''est pour la femme un acte révolutionnaire en soi.', 'Hélène Cixous', 'Française/Algérienne', '''Le Rire de la Méduse'', L''Arc, n°61, 1975','["2025-11-17","2026-12-21","2028-01-24","2029-02-26","2030-04-01"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f10e1283', '有教無類。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre XV, §39, ~500 av. J.-C.','["2025-11-18","2026-12-22","2028-01-25","2029-02-27","2030-04-02"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c19dc6ab', 'La liberté des femmes est liée à la liberté de toute la société.', 'Simone de Beauvoir', 'Française', '''Le Deuxième Sexe'', Tome II, Gallimard, 1949, Conclusion','["2025-11-19","2026-12-23","2028-01-26","2029-02-28","2030-04-03"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0aebdf6b', 'Une femme libre est précisément le contraire d''une femme facile.', 'Simone de Beauvoir', 'Française', '''La Force des choses'', Gallimard, 1963, p. 210','["2025-11-20","2026-12-24","2028-01-27","2029-03-01","2030-04-04"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3ebc4315', 'Pour être libre, il ne faut pas être soumis.', 'Simone de Beauvoir', 'Française', '''Mémoires d''une jeune fille rangée'', Gallimard, 1958','["2025-11-21","2026-12-25","2028-01-28","2029-03-02","2030-04-05"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_003115f2', 'The subjection of women is not merely the legal subordination of one sex, but the perpetuation of mental slavery.', 'John Stuart Mill', 'Britannique', '''The Subjection of Women'', Chapitre IV, 1869','["2025-11-22","2026-12-26","2028-01-29","2029-03-03","2030-04-06"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4c2f760a', 'The feminist conviction that women are fully human.', 'John Stuart Mill', 'Britannique', '''The Subjection of Women'', Chapitre I, 1869','["2025-11-23","2026-12-27","2028-01-30","2029-03-04","2030-04-07"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8789f1a1', 'Aucune femme ne naît soumise; elle le devient sous la contrainte sociale.', 'Friedrich Engels', 'Allemand', '''Der Ursprung der Familie, des Privateigenthums und des Staats'', Chapitre IX, 1884','["2025-11-24","2026-12-28","2028-01-31","2029-03-05","2030-04-08"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ebed722e', 'The enfranchisement of women is the most important question of the present day.', 'Harriet Taylor Mill', 'Britannique', '''The Enfranchisement of Women'', Westminster Review, 1851','["2025-11-25","2026-12-29","2028-02-01","2029-03-06","2030-04-09"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fbee3a5e', 'Il y a deux grandes forces dans le monde : la peur et l''amour. La peur crée la domination, l''amour crée la liberté.', 'Hélène Cixous', 'Française/Algérienne', '''La Venue à l''écriture'', Union Générale d''Éditions, 1977','["2025-11-26","2026-12-30","2028-02-02","2029-03-07","2030-04-10"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f03345f5', 'La révolution ne peut être complète sans l''égalité des sexes.', 'August Bebel', 'Allemand', '''Die Frau und der Sozialismus'', 1879','["2025-11-27","2026-12-31","2028-02-03","2029-03-08","2030-04-11"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1d583e54', 'La vraie émancipation de la femme, c''est celle qui responsabilise la femme.', 'Thomas Sankara', 'Burkinabé', 'thomassankara.net | Dicocitations | Babelio','["2025-11-28","2027-01-01","2028-02-04","2029-03-09","2030-04-12"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5fdd95e0', 'Si la femme est libre, le monde est libre.', 'Victor Hugo', 'Français', '''Les Misérables'', Tome IV, Gallimard, 1862','["2025-11-29","2027-01-02","2028-02-05","2029-03-10","2030-04-13"]',  'verified', 'tp_femme_et_emancipation');
INSERT INTO topics (id, name) VALUES ('tp_nature_et_univers', 'Nature & Univers');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2dddfb73', 'The Cosmos is all that is or was or ever will be.', 'Carl Sagan', 'Américain', '''Cosmos'', Random House, 1980, Chapitre 1 — première phrase du livre','["2025-11-30","2027-01-03","2028-02-06","2029-03-11","2030-04-14"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1ae397f8', 'We are made of star-stuff.', 'Carl Sagan', 'Américain', '''Cosmos'', Random House, 1980','["2025-12-01","2027-01-04","2028-02-07","2029-03-12","2030-04-15"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_eb3bfa55', 'ἡ φύσις οὐδὲν ποιεῖ μάτην.', 'Aristote', 'Grec', '''Περὶ ζῴων μορίων (Peri zōōn moriōn)'', Livre I, ~350 av. J.-C.','["2025-12-02","2027-01-05","2028-02-08","2029-03-13","2030-04-16"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2c0a2250', 'L''infini grand et l''infiniment petit se rejoignent dans l''immensité de l''univers.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 199 (Les deux infinis), 1670 (posthume)','["2025-12-03","2027-01-06","2028-02-09","2029-03-14","2030-04-17"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_21ee4441', '千里之行，始於足下。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 64 — confirmé par Wikipedia, Taoism.net et multiple traductions académiques','["2025-12-04","2027-01-07","2028-02-10","2029-03-15","2030-04-18"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_6e08ebb2', 'The universe is not only queerer than we suppose, but queerer than we can suppose.', 'J.B.S. Haldane', 'Britannique', '''Possible Worlds and Other Papers'', Chatto & Windus, 1927','["2025-12-05","2027-01-08","2028-02-11","2029-03-16","2030-04-19"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_37c4c682', 'Il faut cultiver notre jardin.', 'Voltaire', 'Français', '''Candide, ou l''Optimisme'', 1759 — dernière réplique','["2025-12-06","2027-01-09","2028-02-12","2029-03-17","2030-04-20"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d6202aac', 'Dieu, c''est-à-dire la Nature.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie IV, Préface (''Deus, sive Natura''), 1677','["2025-12-07","2027-01-10","2028-02-13","2029-03-18","2030-04-21"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_294a234d', 'Tout ce qui est, est en Dieu, et rien ne peut être ni être conçu sans Dieu.', 'Baruch Spinoza', 'Néerlandais', '''Ethica Ordine Geometrico Demonstrata'', Partie I, Proposition XV, 1677','["2025-12-08","2027-01-11","2028-02-14","2029-03-19","2030-04-22"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_78db5f1a', 'La durée réelle est ce que nous avons toujours appelé le temps, mais perçu comme indivisible.', 'Henri Bergson', 'Français', '''Essai sur les données immédiates de la conscience'', PUF, 1889, Chapitre II','["2025-12-09","2027-01-12","2028-02-15","2029-03-20","2030-04-23"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b3abb19f', 'L''élan vital pousse la vie à se surpasser continuellement.', 'Henri Bergson', 'Français', '''L''Évolution créatrice'', PUF, 1907, Chapitre II','["2025-12-10","2027-01-13","2028-02-16","2029-03-21","2030-04-24"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b6e5a803', 'Jede Monade ist ein lebendiger Spiegel des Universums.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''La Monadologie'', §56, 1714','["2025-12-11","2027-01-14","2028-02-17","2029-03-22","2030-04-25"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_af90147b', 'Die Gegenwart ist mit der Vergangenheit schwanger und trägt die Zukunft in sich.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''Nouveaux essais sur l''entendement humain'', Livre IV, Chapitre 16, §13, 1704','["2025-12-12","2027-01-15","2028-02-18","2029-03-23","2030-04-26"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_157d1919', 'Le silence éternel de ces espaces infinis m''effraie.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 206, 1670 (posthume)','["2025-12-13","2027-01-16","2028-02-19","2029-03-24","2030-04-27"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8508adc1', '生死為一條。', 'Zhuangzi', 'Chinois', '''莊子 (Zhuāngzǐ)'', Chapitre VI (''Le grand ancêtre et maître''), ~300 av. J.-C.','["2025-12-14","2027-01-17","2028-02-20","2029-03-25","2030-04-28"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_22aff047', 'الكون كلٌّ منظم تعكس كل جزء منه الكل.', 'Ibn Sina (Avicenne)', 'Perse (Ouzbékistan)', '''Le Livre de la guérison'', Τὰ μετὰ τὰ φυσικά (Ta meta ta physika), §8, ~1020','["2025-12-15","2027-01-18","2028-02-21","2029-03-26","2030-04-29"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_396724ee', 'L''univers est une machine à faire des dieux.', 'Henri Bergson', 'Français', '''Les Deux Sources de la morale et de la religion'', PUF, 1932, Conclusion','["2025-12-16","2027-01-19","2028-02-22","2029-03-27","2030-04-30"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fafbf4d2', 'L''Afrique est le continent où l''humanité a effectué ses premiers pas.', 'Cheikh Anta Diop', 'Sénégalais', '''L''Unité culturelle de l''Afrique noire'', Présence Africaine, 1959, p. 9','["2025-12-17","2027-01-20","2028-02-23","2029-03-28","2030-05-01"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b599ecb9', 'La matière est habitude prise ; l''esprit est habitude contractée.', 'Henri Bergson', 'Français', '''Matière et mémoire'', PUF, 1896, Conclusion','["2025-12-18","2027-01-21","2028-02-24","2029-03-29","2030-05-02"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_8756dcdd', '道可道，非常道；名可名，非常名。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 1, ~VIe siècle av. J.-C.','["2025-12-19","2027-01-22","2028-02-25","2029-03-30","2030-05-03"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4ca0c584', 'La nature est partout; il n''y a pas de vide dans l''univers.', 'Gottfried Wilhelm Leibniz', 'Allemand', '''La Monadologie'', §3, 1714','["2025-12-20","2027-01-23","2028-02-26","2029-03-31","2030-05-04"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ff5abd6c', 'Le plus grand miracle du monde, c''est le monde lui-même.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 267, 1670 (posthume)','["2025-12-21","2027-01-24","2028-02-27","2029-04-01","2030-05-05"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_729618ff', 'La nature n''a ni noyau ni écorce : elle est tout à la fois.', 'Johann Wolfgang von Goethe', 'Allemand', '''Maximen und Reflexionen'', §575, 1833 (posthume)','["2025-12-22","2027-01-25","2028-02-28","2029-04-02","2030-05-06"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9c3d6fbf', 'La nature est un temple où de vivants piliers laissent parfois sortir de confuses paroles.', 'Charles Baudelaire', 'Français', '''Correspondances'', in ''Les Fleurs du mal'', 1857','["2025-12-23","2027-01-26","2028-02-29","2029-04-03","2030-05-07"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f5e8c1c0', 'This preservation of favourable variations and the rejection of injurious variations, I call Natural Selection.', 'Charles Darwin', 'Britannique', '''On the Origin of Species'', John Murray, 1859, Chapitre III','["2025-12-24","2027-01-27","2028-03-01","2029-04-04","2030-05-08"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_72668cad', 'Dans les forêts, il y a quelque chose de mystérieusement vivant.', 'Jean-Jacques Rousseau', 'Suisse/Français', '''Les Rêveries du promeneur solitaire'', Cinquième promenade, 1782','["2025-12-25","2027-01-28","2028-03-02","2029-04-05","2030-05-09"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_dad38ed9', 'L''infiniment grand me dépasse ; l''infiniment petit me contient.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 199, 1670 (posthume)','["2025-12-26","2027-01-29","2028-03-03","2029-04-06","2030-05-10"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ce36237a', 'Nous sommes de la même substance que les songes.', 'William Shakespeare', 'Britannique', '''The Tempest'', Acte IV, Scène I, 1611','["2025-12-27","2027-01-30","2028-03-04","2029-04-07","2030-05-11"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_248cdef2', 'Le monde est beau parce qu''il périt.', 'Albert Camus', 'Français/Algérien', '''Noces'', Gallimard, 1938','["2025-12-28","2027-01-31","2028-03-05","2029-04-08","2030-05-12"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7f55aaf3', 'La Terre tourne, et les empires s''effondrent, mais la nature reste.', 'Leonardo da Vinci', 'Italien', 'Codici, ~1495 — Bibliothèque Ambrosienne, Milan','["2025-12-29","2027-02-01","2028-03-06","2029-04-09","2030-05-13"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_7d971584', 'Πάντα ὕδωρ.', 'Thalès de Milet', 'Grec', 'Rapporté par Aristote, ''Τὰ μετὰ τὰ φυσικά (Ta meta ta physika)'', Livre I, §3 (983b6), ~335 av. J.-C.','["2025-12-30","2027-02-02","2028-03-07","2029-04-10","2030-05-14"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_919eff22', 'Πάντα ῥεῖ.', 'Héraclite', 'Grec', 'Fragment DK22B91 — rapporté par Platon dans ''Cratyle'', 402a','["2025-12-31","2027-02-03","2028-03-08","2029-04-11","2030-05-15"]',  'verified', 'tp_nature_et_univers');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d0563350', 'Nature, to be commanded, must be obeyed.', 'Francis Bacon', 'Britannique', '''Novum Organum Scientiarum'', §3, 1620','["2026-01-01","2027-02-04","2028-03-09","2029-04-12","2030-05-16"]',  'verified', 'tp_nature_et_univers');
INSERT INTO topics (id, name) VALUES ('tp_amour_et_relations', 'Amour & Relations');
INSERT INTO series_topics (series_id, topic_id) VALUES ('sr_saison1', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c42a703d', 'Aimer, ce n''est pas se regarder l''un l''autre, c''est regarder ensemble dans la même direction.', 'Antoine de Saint-Exupéry', 'Français', '''Terre des hommes'', Gallimard, 1939, Chapitre 8','["2026-01-02","2027-02-05","2028-03-10","2029-04-13","2030-05-17"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1375cefc', 'Le cœur a ses raisons que la raison ne connaît point.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 277, 1670 (posthume)','["2026-01-03","2027-02-06","2028-03-11","2029-04-14","2030-05-18"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_616b93d7', 'Amicus est tamquam alter idem.', 'Cicéron', 'Romain', '''Laelius de Amicitia'', §21, ~44 av. J.-C.','["2026-01-04","2027-02-07","2028-03-12","2029-04-15","2030-05-19"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_c89c17a1', 'Es ist nicht der Mangel der Liebe, sondern der Mangel der Freundschaft, der die Ehen unglücklich macht.', 'Friedrich Nietzsche', 'Allemand', '''Menschliches, Allzumenschliches'', §393, 1878','["2026-01-05","2027-02-08","2028-03-13","2029-04-16","2030-05-20"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a4cafcf1', 'Friendship doubles joys, and halves griefs.', 'Francis Bacon', 'Britannique', '''Essays or Counsels, Civil and Moral'', ''Of Friendship'', §27, 1625','["2026-01-06","2027-02-09","2028-03-14","2029-04-17","2030-05-21"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1aa85596', 'Un seul être vous manque, et tout est dépeuplé.', 'Alphonse de Lamartine', 'Français', '''L''Isolement'', in ''Méditations poétiques'', 1820','["2026-01-07","2027-02-10","2028-03-15","2029-04-18","2030-05-22"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ed9fc112', 'A un interlocuteur qui me demandait ce que l''Afrique pourrait apporter, j''ai répondu : ''le rire, que vous avez perdu.''', 'Amadou Hampâté Bâ', 'Malien', '''Aspects de la civilisation africaine'', Présence Africaine, 1972, p. 21-22','["2026-01-08","2027-02-11","2028-03-16","2029-04-19","2030-05-23"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1ab93abd', '克己復禮為仁。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre XII, §1, ~500 av. J.-C.','["2026-01-09","2027-02-12","2028-03-17","2029-04-20","2030-05-24"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_80daab45', 'ἡ γέννησις ἐν τῷ καλῷ.', 'Platon', 'Grec', '''Συμπόσιον (Symposion)'', 206e, ~380 av. J.-C.','["2026-01-10","2027-02-13","2028-03-18","2029-04-21","2030-05-25"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_f485ba18', 'Ce que j''appelle l''amour véritable, c''est l''amour de l''âme pour l''âme.', 'Platon', 'Grec', '''Φαῖδρος (Phaidros)'', 256e, ~370 av. J.-C.','["2026-01-11","2027-02-14","2028-03-19","2029-04-22","2030-05-26"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a382d4fb', 'Your pain is the breaking of the shell that encloses your understanding.', 'Khalil Gibran', 'Libanais', '''The Prophet'', Alfred A. Knopf, 1923, ''De la douleur''','["2026-01-12","2027-02-15","2028-03-20","2029-04-23","2030-05-27"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_14131162', 'Your children are not your children. They are the sons and daughters of Life''s longing for itself.', 'Khalil Gibran', 'Libanais', '''The Prophet'', Alfred A. Knopf, 1923, ''Des enfants''','["2026-01-13","2027-02-16","2028-03-21","2029-04-24","2030-05-28"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_2ef75530', 'Work is love made visible.', 'Khalil Gibran', 'Libanais', '''The Prophet'', Alfred A. Knopf, 1923, ''Du travail''','["2026-01-14","2027-02-17","2028-03-22","2029-04-25","2030-05-29"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_cc7c2aee', 'On ne voit bien qu''avec le cœur ; l''essentiel est invisible pour les yeux.', 'Antoine de Saint-Exupéry', 'Français', '''Le Petit Prince'', Gallimard, 1943, Chapitre XXI','["2026-01-15","2027-02-18","2028-03-23","2029-04-26","2030-05-30"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_aa4072b3', 'Tu deviens responsable pour toujours de ce que tu as apprivoisé.', 'Antoine de Saint-Exupéry', 'Français', '''Le Petit Prince'', Gallimard, 1943, Chapitre XXI','["2026-01-16","2027-02-19","2028-03-24","2029-04-27","2030-05-31"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3063a073', 'Bonheur ou malheur dépendent entièrement de la qualité de l''objet que nous aimons.', 'Baruch Spinoza', 'Néerlandais', '''Tractatus de Intellectus Emendatione'', §9, 1677','["2026-01-17","2027-02-20","2028-03-25","2029-04-28","2030-06-01"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_1ad355cf', '君子求諸己，小人求諸人。', 'Confucius', 'Chinois', '''論語 (Lúnyǔ — Analectes)'' (Analectes), Livre XV, §21, ~500 av. J.-C.','["2026-01-18","2027-02-21","2028-03-26","2029-04-29","2030-06-02"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_0dfb1a28', 'Toute l''infortune des hommes vient d''une seule chose : ne savoir pas demeurer en repos dans une chambre.', 'Blaise Pascal', 'Français', '''Pensées'', fragment 139, 1670 (posthume)','["2026-01-19","2027-02-22","2028-03-27","2029-04-30","2030-06-03"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9d5ad723', 'Parce que c''était lui, parce que c''était moi.', 'Michel de Montaigne', 'Français', '''Essais'', Livre I, Chapitre 28, 1580 — sur son amitié avec La Boétie','["2026-01-20","2027-02-23","2028-03-28","2029-05-01","2030-06-04"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_9644231d', 'Ita fac, mi Lucili: vindica te tibi.', 'Sénèque', 'Romain', '''Epistulae Morales ad Lucilium'', Lettre I, ~65 ap. J.-C.','["2026-01-21","2027-02-24","2028-03-29","2029-05-02","2030-06-05"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_ea1f313c', 'درد عشق از مرگ بی‌تفاوتی بهتر است.', 'Rumi', 'Perse (Afghanistan)', '''مثنوی معنوی (Masnavi-ye Ma''navi)'', Livre I, vers 110, XIIIe siècle','["2026-01-22","2027-02-25","2028-03-30","2029-05-03","2030-06-06"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_45760403', 'Love is an active power in man; a power which breaks through the walls which separate man from his fellow men.', 'Erich Fromm', 'Allemand/Américain', '''The Art of Loving'', HarperCollins, 1956, p. 26','["2026-01-23","2027-02-26","2028-03-31","2029-05-04","2030-06-07"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_32cd31af', 'Mature love says: I need you because I love you. Immature love says: I love you because I need you.', 'Erich Fromm', 'Allemand/Américain', '''The Art of Loving'', HarperCollins, 1956, p. 23','["2026-01-24","2027-02-27","2028-04-01","2029-05-05","2030-06-08"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fbf59706', 'Aimer, c''est accepter de ne pas comprendre l''autre entièrement.', 'Gabriel Marcel', 'Français', '''Être et Avoir'', Aubier-Montaigne, 1935','["2026-01-25","2027-02-28","2028-04-02","2029-05-06","2030-06-09"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d7c84931', 'On ne peut être véritablement ami que de quelqu''un de meilleur que soi.', 'Aristote', 'Grec', '''Ethica Ordine Geometrico Demonstrata à Nicomaque'', Livre VIII, Chapitre 3 (1156b), ~335 av. J.-C.','["2026-01-26","2027-03-01","2028-04-03","2029-05-07","2030-06-10"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_d4f2ad50', 'Le mariage est le meilleur et le pire des choses.', 'Aristote', 'Grec', 'Rapporté par Diogène Laërce, ''Vies des philosophes'', Livre V, §19','["2026-01-27","2027-03-02","2028-04-04","2029-05-08","2030-06-11"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_a0577481', 'Was aus Liebe getan wird, geschieht immer jenseits von Gut und Böse.', 'Friedrich Nietzsche', 'Allemand', '''Jenseits von Gut und Böse'', §153, 1886','["2026-01-28","2027-03-03","2028-04-05","2029-05-09","2030-06-12"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_fa94e9a3', 'Die Liebe ist blind; die Freundschaft schließt die Augen.', 'Friedrich Nietzsche', 'Allemand', '''Menschliches, Allzumenschliches'', Vol. II, §394, 1879','["2026-01-29","2027-03-04","2028-04-06","2029-05-10","2030-06-13"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_3468d3c5', 'Les liens les plus forts ne sont pas ceux que l''on choisit mais ceux que la vie impose.', 'Albert Camus', 'Français/Algérien', '''L''Étranger'', Gallimard, 1942','["2026-01-30","2027-03-05","2028-04-07","2029-05-11","2030-06-14"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_4f8586c8', 'عشق را مانند کتابی می‌آموزند، به آرامی.', 'Rumi', 'Perse (Afghanistan)', '''مثنوی معنوی (Masnavi-ye Ma''navi)'', Livre II, vers 1, XIIIe siècle','["2026-01-31","2027-03-06","2028-04-08","2029-05-12","2030-06-15"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_33954c91', '知人者智，自知者明。', 'Lao Tzu', 'Chinois', '''道德經 (Dào Dé Jīng)'', Chapitre 33, ~VIe siècle av. J.-C.','["2026-02-01","2027-03-07","2028-04-09","2029-05-13","2030-06-16"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_5ec465b7', 'Love is the only sane and satisfactory answer to the problem of human existence.', 'Erich Fromm', 'Allemand/Américain', '''The Art of Loving'', HarperCollins, 1956, p. 38','["2026-02-02","2027-03-08","2028-04-10","2029-05-14","2030-06-17"]',  'verified', 'tp_amour_et_relations');
INSERT INTO quotes (id, body, author, nationalite, source, publishAt, statut, topic_id) VALUES ('qt_b4069185', 'La dignité humaine n''est pas un privilège; elle se construit dans la relation à l''autre.', 'Paul Ricoeur', 'Français', '''Soi-même comme un autre'', Seuil, 1990, p. 202','["2026-02-03","2027-03-09","2028-04-11","2029-05-15","2030-06-18"]',  'verified', 'tp_amour_et_relations');
